const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "mysql",
  "inlineSchema": "// Prisma schema.\n// Only the models genuinely needed right now are defined here (P1-05\n// \"modèles initiaux\", ahead of P1-06 authentication). E-Learning, blog and\n// tools models are NOT anticipated — they belong to their own tasks\n// (P2-01, P3-01) per TASKS.md.\n\n// \"prisma-client-js\" (not the newer \"prisma-client\" generator) because it\n// outputs plain, ready-to-run JS + .d.ts — this server has no TypeScript\n// build step, so a TS-source-only client wouldn't run under plain Node.\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\nmodel User {\n  finPushSubscriptions FinPushSubscription[]\n  finMissionAttempts   FinMissionAttempt[]\n  finSnapshots         FinSnapshot[]\n  id                   String                @id @default(uuid())\n  email                String                @unique @db.VarChar(254)\n  passwordHash         String\n  name                 String\n  // Free-form string, not a DB enum: the cahier des charges explicitly\n  // allows adding new account categories later (\"autres catégories\n  // pouvant être ajoutées\"), and a Postgres enum would need a migration\n  // for each new one. Allowed values are validated at the application\n  // layer (see P1-06).\n  accountType          String\n  // \"standard\" | \"premium\" (see TASKS.md section 1, \"Accès aux\n  // fonctionnalités\"). Same free-form-string reasoning as accountType.\n  accessLevel          String                @default(\"standard\")\n  // \"user\" | \"admin\". Orthogonal to accessLevel: role = what you may\n  // manage (RBAC), accessLevel = which content tier you may consume.\n  // Never settable from a public endpoint (see auth.schemas.js).\n  role                 String                @default(\"user\")\n  // \"active\" | \"suspended\" (P3-16). Checked on every request (requireAuth), so\n  // suspending an account takes effect immediately, on the same session.\n  status               String                @default(\"active\")\n  createdAt            DateTime              @default(now())\n  updatedAt            DateTime              @updatedAt\n\n  // ---- FINCLUDIA publics (P3-18) --------------------------------------------\n  // The FINCLUDIA profile a user has chosen (one of the 8 publics of the\n  // client's own file, onglet \"01_Publics\": LYC/ETU/JAC/SAL/COL/COU/FAM/EPG),\n  // null until the person has gone through onboarding (C01/C02). Per the\n  // client's decision (2026-10-11): a user has ONE profile at a time — once\n  // finPublic is set, it is what defines the account, not `accountType`\n  // (kept only for the pre-FINCLUDIA features that still read it: comparator\n  // segments, article targeting...).\n  finPublic               String?\n  // Complementary roles (ex. SAL primary + COL complementary), same closed\n  // list as finPublic, never containing finPublic itself. Free-form JSON\n  // array of codes (small, bounded, validated at the application layer) —\n  // not a join table: there is no extra data attached to a secondary role.\n  finSecondaryPublics     Json                   @default(\"[]\")\n  // Age bracket, not a birth date: the server only ever needs to know whether\n  // someone is \"under18\" (the 18+ gate, already settled project-wide) — a\n  // precise date of birth would be more personal data than that requires\n  // (rule 10, minimisation). The exact minimum age to register, and parental\n  // consent, remain open (P6-01 point 7) — this column is ready for both.\n  finAgeRange             String?\n  finCountry              String?                @db.VarChar(2)\n  // ISO 4217, defaults to DZD (the only currency used anywhere in the\n  // platform today): a placeholder until multi-currency is decided (P6-01\n  // point 4), never shown as a final decision.\n  finCurrency             String                 @default(\"DZD\") @db.VarChar(3)\n  finSituation            String?\n  finMainIntention        String?\n  finHorizon              String?\n  finOnboardedAt          DateTime?\n  // Target months of essential expenses the person wants set aside (screen C12,\n  // P6-09). Null until THEY choose it: a default would be an invented\n  // recommendation, which the client's own wording (\"cible choisie par\n  // l'utilisateur\") rules out — F015/F016 read null as \"non calculé\", not 0.\n  finReserveTargetMonths  Int?\n  // « Régularité du revenu = Stable | Irrégulier | Saisonnier » (the client's\n  // answer C3, 2026-10-28): declared by the person, never changed by the\n  // system. Irregular or seasonal raises the emergency fund's default target\n  // to 6 months. `stable` | `irregular` | `seasonal` (FIN_INCOME_REGULARITIES).\n  finIncomeRegularity     String                 @default(\"stable\") @db.VarChar(10)\n  // « Premiers pas » (P8-23, tab 02_Premier_Demarrage): the steps the person\n  // chose to skip for now, { \"P4\": true }. A step is done when its data exists;\n  // nothing here is ever a gate.\n  finFirstSteps           Json                   @default(\"{}\")\n  // Per-type enable/opt-in (P6-18): { [type]: { enabled, optedIn } }. Absent\n  // keys fall back to the catalogue's own default (constants/finNotification.js)\n  // — this column only ever holds what someone actually changed.\n  finNotificationSettings Json                   @default(\"{}\")\n  finProfileTransitions   FinProfileTransition[]\n  finConsents             FinConsent[]\n  finAuditLogs            FinAuditLog[]\n  learningFavorites       LearningFavorite[]\n  finCategories           FinCategory[]\n  finChanges              FinChange[]\n  finIncomes              FinIncome[]\n  finTransactions         FinTransaction[]\n  finAccounts             FinAccount[]\n  finOccurrences          FinOccurrence[]\n  finPayslips             FinPayslip[]\n  toolFavorites           ToolFavorite[]\n  finTags                 FinTag[]\n  sessions                UserSession[]\n  finOnboarding           FinOnboarding?\n  finBudgets              FinBudget[]\n  finEnvelopes            FinEnvelope[]\n  finRecurrences          FinRecurrence[]\n  finProvisions           FinProvision[]\n  finAssets               FinAsset[]\n  finSpaceMemberships     FinSpaceMember[]\n  finPaperPortfolio       FinPaperPortfolio?\n  finSpaceInvitesSent     FinSpaceInvite[]       @relation(\"SpaceInviteSender\")\n  finSpaceInvitesTaken    FinSpaceInvite[]       @relation(\"SpaceInviteAcceptor\")\n  finGoals                FinGoal[]\n  finDebts                FinDebt[]\n  finDebtPayments         FinDebtPayment[]\n  finNotifications        FinNotification[]\n  finBusiness             FinBusiness?\n\n  // E-Learning (P2-01)\n  formationsCreated Formation[]\n  mediaUploaded     Media[]\n  enrollments       Enrollment[]\n\n  // Blog (P3-01)\n  articlesAuthored Article[]\n\n  // CMS (P3-12)\n  lessonRevisions LessonRevision[]\n\n  // Simulation workshop (P4-16)\n  simulationScenarios SimulationScenario[]\n\n  // Payment (P3-09)\n  paymentOrders PaymentOrder[]\n\n  @@map(\"users\")\n}\n\n// A simulation the user chose to keep (P4-16, screen C18). The client's rule for\n// this screen is explicit: \"hypothèses sauvegardées avec résultat\" and \"chaque\n// simulateur porte version de formule\". Hence three JSON columns instead of one:\n//\n//   inputs      what the person typed, in the units of the engine (centimes,\n//               decimal rates). The results are RECOMPUTED from these on every\n//               read-back, so a scenario is never a screenshot of numbers whose\n//               origin nobody can check.\n//   hypotheses  the assumptions the simulation ran under (a monthly return, an\n//               inflation rate, an horizon), as the simulator returned them.\n//   versions    { Fxxx: version } for every formula the result used.\n//\n// Why the versions are stored rather than looked up: a formula may change after\n// the scenario was saved. Keeping the version it ran under is what lets the\n// screen say, a year later, \"this figure came from F021 version 1\" instead of\n// silently showing a different number under the same name.\nmodel SimulationScenario {\n  id         String   @id @default(uuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  // Key of a simulator of constants/simulators.js. Free-form string, like the\n  // other application-level vocabularies here: the catalogue grows with the\n  // client's lots, and a DB enum would need a migration for each one.\n  simulator  String\n  // The name the person gave this scenario, to tell two of them apart.\n  title      String   @db.VarChar(120)\n  // ISO code the amounts are expressed in. Stored with the scenario: comparing\n  // two scenarios in different currencies is refused, never converted.\n  currency   String   @db.VarChar(3)\n  inputs     Json\n  hypotheses Json?\n  versions   Json     @default(\"{}\")\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@index([userId, createdAt])\n  @@map(\"simulation_scenarios\")\n}\n\n// ---- Payment (P3-09): provider-independent base ------------------------------\n// What can be bought. Prices are entered by an administrator from the client's\n// figures (never invented). Amounts are INTEGERS in the currency's smallest unit\n// (centimes...): no floating point anywhere in money.\nmodel PaymentOffer {\n  id          String         @id @default(uuid())\n  name        String         @db.VarChar(120)\n  description String?        @db.Text\n  amount      Int\n  // ISO 4217 code, upper case (\"DZD\", \"EUR\").\n  currency    String         @db.VarChar(3)\n  // Access level the purchase grants. Only \"premium\" exists today (P1-06, P3-04).\n  accessLevel String         @default(\"premium\") @db.VarChar(20)\n  isActive    Boolean        @default(false)\n  position    Int            @default(0)\n  createdAt   DateTime       @default(now())\n  updatedAt   DateTime       @updatedAt\n  orders      PaymentOrder[]\n\n  @@map(\"payment_offers\")\n}\n\n// One purchase attempt. Amount, currency and access level are COPIED from the\n// offer when the order is created: changing an offer's price later never changes\n// what an existing order is worth. Orders are kept for accounting: an offer or a\n// user with orders cannot be deleted (RESTRICT).\nmodel PaymentOrder {\n  id                String         @id @default(uuid())\n  userId            String\n  user              User           @relation(fields: [userId], references: [id], onDelete: Restrict)\n  offerId           String\n  offer             PaymentOffer   @relation(fields: [offerId], references: [id], onDelete: Restrict)\n  amount            Int\n  currency          String         @db.VarChar(3)\n  accessLevel       String         @db.VarChar(20)\n  // pending | paid | failed | cancelled | refunded (CHECK in the migration).\n  status            String         @default(\"pending\") @db.VarChar(20)\n  provider          String         @db.VarChar(30)\n  // The provider's id for the checkout session: how its notifications find the order.\n  providerReference String?        @unique @db.VarChar(191)\n  paidAt            DateTime?\n  refundedAt        DateTime?\n  createdAt         DateTime       @default(now())\n  updatedAt         DateTime       @updatedAt\n  events            PaymentEvent[]\n\n  @@index([userId, createdAt])\n  @@index([status])\n  @@map(\"payment_orders\")\n}\n\n// Every notification received from a provider, once: the UNIQUE (provider,\n// externalId) pair is what makes a replayed or duplicated notification a no-op.\n// Only what is needed to audit the outcome is kept, never the raw payload\n// (it may hold personal data).\nmodel PaymentEvent {\n  id         String        @id @default(uuid())\n  provider   String        @db.VarChar(30)\n  externalId String        @db.VarChar(191)\n  type       String        @db.VarChar(60)\n  orderId    String?\n  order      PaymentOrder? @relation(fields: [orderId], references: [id], onDelete: SetNull)\n  // What processing did: applied | ignored | unknown_order | amount_mismatch.\n  outcome    String        @db.VarChar(30)\n  receivedAt DateTime      @default(now())\n\n  @@unique([provider, externalId])\n  @@map(\"payment_events\")\n}\n\n// ---- FINCLUDIA publics (P3-18) ------------------------------------------------\n// Changing public is proposed, never forced: a user switches by their own\n// action (ex. \"étudiant\" -> \"jeune actif\" at the first salary), and every\n// switch is kept here so the account's own history is never lost.\nmodel FinProfileTransition {\n  id         String   @id @default(uuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  fromPublic String?\n  toPublic   String\n  createdAt  DateTime @default(now())\n\n  @@index([userId, createdAt])\n  @@map(\"fin_profile_transitions\")\n}\n\n// A consent the person explicitly accepted, with the exact version of the text\n// at the time (P6-01 point 9): re-accepting after a text changes adds a new\n// row, it never overwrites the old one — the account's consent history stays\n// intact exactly like the profile transitions above.\nmodel FinConsent {\n  id         String   @id @default(uuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  // \"finPrivacy\" | \"finNoAdvice\" (constants/finPublics.js), never free-form.\n  textKey    String   @db.VarChar(40)\n  version    String   @db.VarChar(20)\n  acceptedAt DateTime @default(now())\n\n  @@index([userId, textKey])\n  @@map(\"fin_consents\")\n}\n\n// A piece of \"Apprendre\" content someone kept (P2-08, the client's \"favoris\").\n// `kind` says which table `refId` points into (\"course\" | \"article\" | \"term\" |\n// \"guide\"), validated at the application layer against one closed list. No\n// foreign key on purpose: four nullable columns, three of them always null,\n// would be a worse model than one typed reference, and a favourite pointing at\n// content that has since been deleted or unpublished is simply dropped when the\n// list is read.\n// The favourite tools of the single catalogue (P8-15, OUT-01). A code of\n// constants/finToolsCatalogue.js, not a foreign key: the catalogue is a\n// constant, and a code that leaves it simply stops being shown.\nmodel ToolFavorite {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  code      String   @db.VarChar(20)\n  createdAt DateTime @default(now())\n\n  @@unique([userId, code])\n  @@index([userId, createdAt])\n  @@map(\"tool_favorites\")\n}\n\nmodel LearningFavorite {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  kind      String   @db.VarChar(20)\n  refId     String\n  createdAt DateTime @default(now())\n\n  @@unique([userId, kind, refId])\n  @@index([userId, createdAt])\n  @@map(\"learning_favorites\")\n}\n\n// ---- FINCLUDIA common financial data model (P6-02) ---------------------------\n// THE METADATA SOCLE. The client's onglet \"04_Donnees_Objets\" lists the metadata\n// every important financial datum must carry; it is written once here and\n// repeated identically by every financial table of Phase 6, so a reader finds\n// the same columns with the same meaning everywhere:\n//\n//   scope       String    @default(\"personal\") @db.VarChar(20)  // perimetre\n//   source      String    @db.VarChar(20)                       // how it got in\n//   sourceRef   String?   @db.VarChar(200)                      // reference_source\n//   status      String    @db.VarChar(20)                       // reel/declare/fictif...\n//   confidence  String?   @db.VarChar(10)                       // \"lorsque pertinent\"\n//   consentUses Json      @default(\"[]\")                        // usages autorises\n//   effectiveAt DateTime                                        // date_effet\n//   collectedAt DateTime  @default(now())                       // date_collecte\n//   version     Int       @default(1)\n//   archivedAt  DateTime?                                       // hidden, still there\n//   deletedAt   DateTime?                                       // logical delete\n//\n// plus `value` (an INTEGER amount, smallest unit) and `currency` (ISO 4217) on\n// every table that carries an amount. The allowed values of each vocabulary are\n// in constants/finData.js, validated by zod AND by a SQL CHECK.\n//\n// A row that feeds a history is never erased: `deletedAt` is set and a\n// `FinChange` row says what happened. Physical deletion is reserved for a row\n// nothing has used yet, and for the account-wide erasure the privacy text\n// promises (P6-01 point 9, ON DELETE CASCADE below).\n\n// A category of the client's reference (onglet \"03_Categories\"), or one a user\n// made. Three shapes, and nothing else (the consistency control enforces it):\n//   - standard:  userId null, `key` set, `baseKey` null   -- global, read-only\n//   - own:       userId set,  `key` null, `baseKey` null  -- the user's own label\n//   - override:  userId set,  `key` null, `baseKey` set   -- this user renames or\n//                hides (archivedAt) the standard row of that key, for themselves\n//                only; the standard row itself is never touched.\n//\n// A category names a line, it is not a line: it carries the socle except\n// `value`, `currency` and `confidence`, which would be null on every row.\nmodel FinCategory {\n  id                String             @id @default(uuid())\n  userId            String?\n  user              User?              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  // One of CATEGORY_FAMILY_CODES (constants/finCategories.js).\n  family            String             @db.VarChar(20)\n  key               String?            @unique @db.VarChar(80)\n  baseKey           String?            @db.VarChar(80)\n  label             String             @db.VarChar(80)\n  // From the client's universal reference (P8-08, `09_Categories`): the\n  // category a sub-category belongs to, its icon and colour, whether it is an\n  // essential expense, its typical recurrence, and the profiles it is SUGGESTED\n  // for (a display order, never a restriction). On a user's override,\n  // `essential` null means « as the reference says ».\n  group             String?            @db.VarChar(60)\n  icon              String?            @db.VarChar(16)\n  color             String?            @db.VarChar(9)\n  essential         Boolean?\n  recurrence        String?            @db.VarChar(40)\n  suggestedFor      Json               @default(\"[]\")\n  scope             String             @default(\"personal\") @db.VarChar(20)\n  source            String             @db.VarChar(20)\n  sourceRef         String?            @db.VarChar(200)\n  status            String             @db.VarChar(20)\n  consentUses       Json               @default(\"[]\")\n  effectiveAt       DateTime           @default(now())\n  collectedAt       DateTime           @default(now())\n  version           Int                @default(1)\n  archivedAt        DateTime?\n  deletedAt         DateTime?\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  finIncomes        FinIncome[]\n  finTransactions   FinTransaction[]\n  finEnvelopes      FinEnvelope[]\n  finRecurrences    FinRecurrence[]\n  finProvisions     FinProvision[]\n  finAssets         FinAsset[]\n  finSharedExpenses FinSharedExpense[]\n  finTagsAuto       FinTag[]\n\n  // One customisation of a given standard row per account, at most.\n  @@unique([userId, baseKey])\n  @@index([userId, family])\n  @@map(\"fin_categories\")\n}\n\n// The correction trail. One row per thing that happened to a financial datum,\n// in the account that owns it: what object, which field, the value before and\n// the value after. `reason` is the sentence the person typed if the interface\n// asked for one — never required, never invented.\n//\n// Only the owner ever writes financial data (self-service; an administrator has\n// no screen that edits someone's money), so the actor is always the account in\n// `userId` and there is no second identity to keep here.\nmodel FinChange {\n  id        String   @id @default(uuid())\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  // Which kind of object: \"category\" today, then \"income\", \"transaction\"...\n  entity    String   @db.VarChar(40)\n  entityId  String\n  // One of CHANGE_ACTIONS (constants/finData.js).\n  action    String   @db.VarChar(20)\n  field     String?  @db.VarChar(40)\n  before    Json?\n  after     Json?\n  reason    String?  @db.VarChar(200)\n  createdAt DateTime @default(now())\n\n  @@index([entity, entityId, createdAt])\n  @@index([userId, createdAt])\n  @@map(\"fin_changes\")\n}\n\n// ---- FINCLUDIA \"Mon argent\" (P6-04) and onboarding (P6-03) -------------------\n// Both reuse the metadata socle documented above FinCategory: the same columns,\n// with the same meaning, plus `value` and `currency` where there is an amount.\n// Amounts are INTEGERS in the smallest unit of the currency, and the currency is\n// always stored next to its amount — nothing is ever converted without a dated\n// rate, so a mixed-currency total answers \"not computable\" instead of guessing.\n\n// A recurring resource (client object \"Revenu\": propriétaire, type, montant,\n// devise, fréquence, date_début, source, statut). `frequency` is NOT nullable\n// on purpose: the client's own error case for screen ET01 is « fréquence\n// manquante pour ressource périodique », and a yearly grant counted monthly\n// would be a twelve-fold lie. A ONE-OFF amount is not a resource — it is a\n// transaction, below.\nmodel FinIncome {\n  id          String       @id @default(uuid())\n  userId      String\n  user        User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label       String       @db.VarChar(80)\n  // The category this resource belongs to. SetNull, never Cascade: losing a\n  // category must never take the money with it. The application NEVER deletes a\n  // category physically anyway (P6-02 deletes logically, so an old total keeps\n  // knowing what its lines were called), so this only ever fires when the whole\n  // account is erased — and then this row is going too, which is exactly what\n  // the privacy text promises (P6-01 point 9). Restrict was wrong here: it made\n  // that erasure fail for anyone who had used a category of their own.\n  categoryId  String?\n  category    FinCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  value       Int\n  currency    String       @db.VarChar(3)\n  // One of FREQUENCIES (constants/finance.js): hebdomadaire, mensuel,\n  // trimestriel, semestriel, annuel. F001 normalises it to the month.\n  frequency   String       @db.VarChar(20)\n  startDate   DateTime\n  endDate     DateTime?\n  scope       String       @default(\"personal\") @db.VarChar(20)\n  source      String       @db.VarChar(20)\n  sourceRef   String?      @db.VarChar(200)\n  status      String       @db.VarChar(20)\n  confidence  String?      @db.VarChar(10)\n  consentUses Json         @default(\"[]\")\n  effectiveAt DateTime     @default(now())\n  collectedAt DateTime     @default(now())\n  version     Int          @default(1)\n  archivedAt  DateTime?\n  deletedAt   DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  @@index([userId, deletedAt])\n  @@index([categoryId])\n  @@map(\"fin_incomes\")\n}\n\n// A dated movement, in or out (screens C07 \"Ajouter une dépense / revenu\" and\n// C08 \"Historique & recherche\"). An uncategorised movement is legitimate and\n// kept apart rather than forced into a category (the client lists\n// « transactions non catégorisées à part »), so `categoryId` is nullable.\n// An account (P8-03, ARC-04): « les comptes sont la source de vérité des\n// soldes ». Its balance is never stored: it is PB-F001, computed from the\n// opening balance and the realised movements, so it can never drift from them.\nmodel FinAccount {\n  id                String           @id @default(uuid())\n  userId            String\n  user              User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label             String           @db.VarChar(80)\n  // One of ACCOUNT_TYPES (AC-01 to AC-10, constants/finAccounts.js): it\n  // decides the nature (asset, liability...).\n  type              String           @db.VarChar(5)\n  currency          String           @db.VarChar(3)\n  openingBalance    Int              @default(0)\n  openingDate       DateTime         @default(now())\n  includeInTotal    Boolean\n  includeInNetWorth Boolean\n  // Null means the type's own colour and icon.\n  color             String?          @db.VarChar(9)\n  icon              String?          @db.VarChar(16)\n  minBalanceAlert   Int?\n  maxBalanceInfo    Int?\n  overdraftAllowed  Int?\n  note              String?          @db.VarChar(300)\n  // The metadata socle every financial row carries (P6-02).\n  scope             String           @default(\"personal\") @db.VarChar(20)\n  source            String           @db.VarChar(20)\n  status            String           @db.VarChar(20)\n  confidence        String?          @db.VarChar(10)\n  consentUses       Json             @default(\"[]\")\n  effectiveAt       DateTime         @default(now())\n  collectedAt       DateTime         @default(now())\n  version           Int              @default(1)\n  archivedAt        DateTime?\n  deletedAt         DateTime?\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n  transactions      FinTransaction[]\n  recurrences       FinRecurrence[]\n  goals             FinGoal[]\n  debts             FinDebt[]\n\n  @@index([userId, deletedAt])\n  @@map(\"fin_accounts\")\n}\n\n// What happened to ONE occurrence of a recurrence (P8-11): confirmed (with\n// the movement it created), not received, or postponed to another day. An\n// occurrence with no row here is simply still expected. One row per\n// recurrence and due date, so a salary can never be credited twice (QA-P05).\nmodel FinOccurrence {\n  id            String        @id @default(uuid())\n  userId        String\n  user          User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  recurrenceId  String\n  recurrence    FinRecurrence @relation(fields: [recurrenceId], references: [id], onDelete: Cascade)\n  dueDate       DateTime\n  // « confirmed » | « missed » | « postponed »\n  outcome       String        @db.VarChar(12)\n  postponedTo   DateTime?\n  transactionId String?       @db.VarChar(191)\n  scope         String        @default(\"personal\") @db.VarChar(20)\n  source        String        @db.VarChar(20)\n  status        String        @db.VarChar(20)\n  confidence    String?       @db.VarChar(10)\n  consentUses   Json          @default(\"[]\")\n  effectiveAt   DateTime      @default(now())\n  collectedAt   DateTime      @default(now())\n  version       Int           @default(1)\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  @@unique([recurrenceId, dueDate])\n  @@index([userId])\n  @@map(\"fin_occurrences\")\n}\n\n// A tag (« étiquette », P8-07, tab 07B): a name and a colour, across\n// categories and accounts. `autoCategoryId` is the client's « option\n// d'appliquer automatiquement aux nouveaux enregistrements similaires »:\n// a new movement in that category, entered without a tag, receives it.\nmodel FinTag {\n  id             String           @id @default(uuid())\n  userId         String\n  user           User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name           String           @db.VarChar(40)\n  color          String           @db.VarChar(9)\n  autoCategoryId String?\n  autoCategory   FinCategory?     @relation(fields: [autoCategoryId], references: [id], onDelete: SetNull)\n  scope          String           @default(\"personal\") @db.VarChar(20)\n  source         String           @db.VarChar(20)\n  status         String           @db.VarChar(20)\n  confidence     String?          @db.VarChar(10)\n  consentUses    Json             @default(\"[]\")\n  effectiveAt    DateTime         @default(now())\n  collectedAt    DateTime         @default(now())\n  version        Int              @default(1)\n  archivedAt     DateTime?\n  deletedAt      DateTime?\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n  transactions   FinTransaction[]\n\n  @@index([userId, deletedAt])\n  @@map(\"fin_tags\")\n}\n\nmodel FinTransaction {\n  // The collective expense paid from this transaction, when there is one (P9-08).\n  sharedExpense FinSharedExpense? @relation(\"SharedExpenseSource\")\n  id            String            @id @default(uuid())\n  userId        String\n  user          User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  // \"income\" | \"expense\" (TRANSACTION_KINDS), or one side of a transfer:\n  // \"transfer_out\" | \"transfer_in\" (TRANSFER_KINDS, P8-03).\n  kind          String            @db.VarChar(12)\n  // The account credited or debited (ARC-04). Nullable in the database only\n  // so the rows written before P8-03 could be migrated; the service always\n  // sets it. Cascade, not Restrict (2026-10-28): the application never deletes\n  // an account, it archives it, so a real deletion only happens when the User\n  // is erased — and with Restrict MariaDB could reach the accounts before the\n  // movements and refuse the whole erasure (same defect as the category key,\n  // P6-04).\n  accountId     String?\n  account       FinAccount?       @relation(fields: [accountId], references: [id], onDelete: Cascade)\n  // The two writes of one transfer share this id (PB-PR-06), and are written\n  // together in one database transaction.\n  transferId    String?           @db.VarChar(36)\n  value         Int\n  currency      String            @db.VarChar(3)\n  occurredAt    DateTime\n  categoryId    String?\n  category      FinCategory?      @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  // Free text, unlike the category: the client asks for a sub-category field\n  // and gives no reference list for it, so inventing a closed one would refuse\n  // answers it means to accept.\n  subcategory   String?           @db.VarChar(60)\n  // One of PM-01 to PM-10 (constants/finAccounts.js, the client's tab\n  // `05B_Moyens_Paiement`, P8-07) — an instrument, never an account.\n  paymentMethod String?           @db.VarChar(20)\n  // « Étiquette » (P8-07): a free cross-cutting mark, name and colour.\n  tagId         String?\n  tag           FinTag?           @relation(fields: [tagId], references: [id], onDelete: SetNull)\n  // Who paid, when it was someone else; never a share (that is Gestion\n  // commune, Phase 9). And where, as the person typed it.\n  payer         String?           @db.VarChar(80)\n  place         String?           @db.VarChar(120)\n  // « Pointage » (tab 08C): unchecked, checked, reconciled, to_verify. It\n  // never changes a balance, only how far the figures can be trusted.\n  clearing      String            @default(\"unchecked\") @db.VarChar(12)\n  note          String?           @db.VarChar(300)\n  // Marked for a shared space by an explicit action, never by default: the\n  // phase rule is « rien n'entre dans un espace partagé sans action explicite ».\n  shared        Boolean           @default(false)\n  // A movement that has not happened yet. The ONLY case where `occurredAt` may\n  // be in the future, and only for an expense (client: « date future seulement\n  // pour une dépense planifiée »).\n  planned       Boolean           @default(false)\n  receipt       Media?            @relation(\"TransactionReceipt\")\n  scope         String            @default(\"personal\") @db.VarChar(20)\n  source        String            @db.VarChar(20)\n  sourceRef     String?           @db.VarChar(200)\n  status        String            @db.VarChar(20)\n  confidence    String?           @db.VarChar(10)\n  consentUses   Json              @default(\"[]\")\n  effectiveAt   DateTime          @default(now())\n  collectedAt   DateTime          @default(now())\n  version       Int               @default(1)\n  archivedAt    DateTime?\n  deletedAt     DateTime?\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n\n  // The history is always read by owner and date, and the duplicate check looks\n  // up the same owner, kind and amount around a date.\n  @@index([userId, occurredAt])\n  @@index([userId, kind, value, occurredAt])\n  @@index([categoryId])\n  @@index([accountId])\n  @@index([transferId])\n  @@index([tagId])\n  @@map(\"fin_transactions\")\n}\n\n// Where someone is in the progressive onboarding (P6-03, screens C03, LY01,\n// ET01, SA01, EP01). One per account.\n//\n// `answers` holds what was answered, keyed by question (constants/\n// finOnboarding.js), with a skipped question recorded AS skipped rather than\n// absent — « Passer » is a real answer and must not look like a question nobody\n// reached. The resource answers also become real FinIncome rows; the amounts\n// whose own table does not exist yet (épargne disponible, mensualités de dette,\n// montant de l'objectif) stay here as DECLARED values until P6-05, P6-08 and\n// P6-11 give them one, and the first budget is computed from them through the\n// versioned engine like any other figure.\nmodel FinOnboarding {\n  id          String    @id @default(uuid())\n  userId      String    @unique\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  currency    String    @db.VarChar(3)\n  answers     Json      @default(\"{}\")\n  // The client's fictional starter budget for a lycéen (« commence avec 5 000 DA\n  // fictifs »). When true every figure of this onboarding is fictional and\n  // carries the SIMULATION badge; it is never added to a real total.\n  fictional   Boolean   @default(false)\n  completedAt DateTime?\n  scope       String    @default(\"personal\") @db.VarChar(20)\n  source      String    @db.VarChar(20)\n  sourceRef   String?   @db.VarChar(200)\n  status      String    @db.VarChar(20)\n  confidence  String?   @db.VarChar(10)\n  consentUses Json      @default(\"[]\")\n  effectiveAt DateTime  @default(now())\n  collectedAt DateTime  @default(now())\n  version     Int       @default(1)\n  archivedAt  DateTime?\n  deletedAt   DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@map(\"fin_onboardings\")\n}\n\n// ---- FINCLUDIA budgets and envelopes (P6-05) ---------------------------------\n// A budget is a PERIOD of one account; an envelope is what that period plans for\n// one category. Both reuse the metadata socle of P6-02.\n//\n// Two tables rather than one JSON column of envelopes: an envelope is corrected\n// on its own, has its own journal trail, and points at a category with a real\n// foreign key — three things a JSON blob cannot do.\n\nmodel FinBudget {\n  id              String        @id @default(uuid())\n  userId          String\n  user            User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label           String        @db.VarChar(80)\n  // The period this budget plans. Two live budgets of one account may never\n  // overlap (client: « chevauchement de périodes refusé »); that rule needs\n  // `userId`, a FOREIGN KEY column, so it lives in the service and in the\n  // consistency control rather than in a CHECK MariaDB would refuse.\n  periodStart     DateTime\n  periodEnd       DateTime\n  currency        String        @db.VarChar(3)\n  // One of BUDGET_RECURRENCES (constants/finBudget.js). `none` is a one-off\n  // budget, which must stay possible: a mandatory recurrence would invent a\n  // commitment nobody made.\n  recurrence      String        @default(\"monthly\") @db.VarChar(20)\n  // The thresholds this budget alerts at, as RATIOS (0.8 = 80 %). Stored per\n  // budget because the client asks for them to be configurable, and visible in\n  // every answer because the engine must never hold a hidden coefficient.\n  alertThresholds Json          @default(\"[0.8, 1]\")\n  // « Report du reste » (P8-09, PB-F008): the positive remainder of the\n  // previous period's envelopes is added to the same envelopes here —\n  // report = max(0 ; reste), the client's answer C1 (2026-10-28).\n  carryOver       Boolean       @default(false)\n  // And, only if the person chooses it (answer C1), last period's overspend\n  // is taken from the same envelopes here. Off by default: an overspend stays\n  // visible in its own month, it does not silently shrink the next one.\n  carryOverspend  Boolean       @default(false)\n  // The person's own pocket for a client category group, for the optional\n  // methods (tab 12B: « le mapping est éditable »). Empty = the defaults.\n  methodMapping   Json          @default(\"{}\")\n  note            String?       @db.VarChar(300)\n  scope           String        @default(\"personal\") @db.VarChar(20)\n  source          String        @db.VarChar(20)\n  sourceRef       String?       @db.VarChar(200)\n  status          String        @db.VarChar(20)\n  confidence      String?       @db.VarChar(10)\n  consentUses     Json          @default(\"[]\")\n  effectiveAt     DateTime      @default(now())\n  collectedAt     DateTime      @default(now())\n  version         Int           @default(1)\n  archivedAt      DateTime?\n  deletedAt       DateTime?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n  envelopes       FinEnvelope[]\n\n  @@index([userId, periodStart])\n  @@map(\"fin_budgets\")\n}\n\n// What one period plans for one category. `value` is the planned amount; `cap`\n// is the client's optional « plafond », a ceiling the person sets for\n// themselves — passing it is SIGNALLED, never refused, because the money has\n// already been spent and refusing it would only make the figure wrong.\n//\n// `categoryId` is nullable like everywhere else in Phase 6 (SetNull), but an\n// envelope without a category makes no sense, so the service never creates one:\n// the column is nullable only so erasing an account cannot be blocked.\nmodel FinEnvelope {\n  id            String       @id @default(uuid())\n  // Denormalised on purpose: every read is « the envelopes of MY budget », and\n  // checking ownership through the budget on each row would be a join per row.\n  // The consistency control checks the two agree.\n  userId        String\n  user          User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  budgetId      String\n  budget        FinBudget    @relation(fields: [budgetId], references: [id], onDelete: Cascade)\n  categoryId    String?\n  category      FinCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  // A client category (« Logement », « Alimentation »…, P8-09) instead of one\n  // sub-category: the envelope then covers every sub-category of the group\n  // that has no envelope of its own (« le plus spécifique », tab 10B). An\n  // envelope has a category OR a group, never both (checked in the service:\n  // MariaDB refuses a CHECK on a foreign-key column).\n  categoryGroup String?      @db.VarChar(60)\n  // One of ENVELOPE_KINDS: the client's own « fixe / variable ».\n  kind          String       @db.VarChar(10)\n  value         Int\n  currency      String       @db.VarChar(3)\n  cap           Int?\n  // Whether this envelope is carried over when the budget is duplicated for the\n  // next period. A one-off envelope (a trip, school fees) must not silently\n  // reappear next month.\n  recurring     Boolean      @default(true)\n  note          String?      @db.VarChar(300)\n  scope         String       @default(\"personal\") @db.VarChar(20)\n  source        String       @db.VarChar(20)\n  sourceRef     String?      @db.VarChar(200)\n  status        String       @db.VarChar(20)\n  confidence    String?      @db.VarChar(10)\n  consentUses   Json         @default(\"[]\")\n  effectiveAt   DateTime     @default(now())\n  collectedAt   DateTime     @default(now())\n  version       Int          @default(1)\n  archivedAt    DateTime?\n  deletedAt     DateTime?\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  @@index([budgetId])\n  @@index([userId, deletedAt])\n  @@index([categoryId])\n  @@map(\"fin_envelopes\")\n}\n\n// ---- Financial goals (P6-08), screens C09-C11 --------------------------------\n// A savings goal: a target, a date, and how much is already set aside. The\n// client's catalogue of templates (constants/finGoal.js) only supplies a label\n// and an icon key — never a suggested amount, which the client explicitly\n// forbids (\"valeurs d'exemple non présélectionnées comme recommandation\").\nmodel FinGoal {\n  id                  String      @id @default(uuid())\n  userId              String\n  user                User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label               String      @db.VarChar(80)\n  // One of GOAL_TEMPLATES (constants/finGoal.js), or null for a fully custom\n  // goal. Purely a starting label/icon; nothing here is read back as data.\n  templateKey         String?     @db.VarChar(40)\n  // « Autre objectif » with its own name, icon and colour (the client's answer\n  // D1, 2026-10-28; C09 in red). Null = the model's icon and colour.\n  icon                String?     @db.VarChar(16)\n  color               String?     @db.VarChar(7)\n  target              Int\n  currency            String      @db.VarChar(3)\n  // \"Date future\" the client asks for at creation. Nullable all the same: a\n  // goal corrected later or a fictional one may lose its date without losing\n  // its meaning, and ALG-03 already reports \"non calculé\" when it is absent.\n  targetDate          DateTime?\n  // \"Capital déjà affecté\". Bounded against this account's own marked savings\n  // (F007) at the service layer — a CHECK cannot read another table — except\n  // for a fictional goal, which plays with money that was never really saved.\n  allocated           Int         @default(0)\n  monthlyContribution Int?\n  // « En cours / Atteint / En pause / Arrêté » (P8-12, tab 10B). Separate\n  // from the socle's `status`, which says how the row is known.\n  progressStatus      String      @default(\"active\") @db.VarChar(10)\n  // The account the goal's money sits on (P8-12, ARC-04): a contribution is\n  // a TRANSFER to it, and the goal's capital is then that account's balance.\n  accountId           String?\n  account             FinAccount? @relation(fields: [accountId], references: [id], onDelete: SetNull)\n  // Annual expected return, a RATIO (0.05 = 5 %), for ALG-03's trajectory. Null\n  // means a simple cash goal: no return is assumed, never invented.\n  rate                Float?\n  priority            Int         @default(0)\n  note                String?     @db.VarChar(300)\n  scope               String      @default(\"personal\") @db.VarChar(20)\n  source              String      @db.VarChar(20)\n  sourceRef           String?     @db.VarChar(200)\n  status              String      @db.VarChar(20)\n  confidence          String?     @db.VarChar(10)\n  consentUses         Json        @default(\"[]\")\n  effectiveAt         DateTime    @default(now())\n  collectedAt         DateTime    @default(now())\n  version             Int         @default(1)\n  archivedAt          DateTime?\n  deletedAt           DateTime?\n  createdAt           DateTime    @default(now())\n  updatedAt           DateTime    @updatedAt\n\n  @@index([userId, deletedAt])\n  @@map(\"fin_goals\")\n}\n\n// ---- Debts (P6-10), screens C13-C14 ------------------------------------------\n// A declared debt: what is left to pay, the instalment, and — when the client\n// knows it — a rate or a known total cost (an informal loan may have neither).\nmodel FinDebt {\n  id                   String           @id @default(uuid())\n  userId               String\n  user                 User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label                String           @db.VarChar(80)\n  lender               String?          @db.VarChar(120)\n  purpose              String?          @db.VarChar(200)\n  // The real asset this debt financed, if any (a car, a flat) — informational\n  // only; linking it to P6-11's patrimony is for when that task exists.\n  assetFinanced        String?          @db.VarChar(120)\n  outstandingPrincipal Int\n  monthlyInstalment    Int\n  currency             String           @db.VarChar(3)\n  // A ratio (0.07 = 7 %) when the client knows it, null otherwise — never\n  // guessed from the instalment, which would invent a rate nobody declared.\n  rate                 Float?\n  // The alternative when the rate is not known: a total cost already declared\n  // by the lender (a store credit's fixed total, for instance).\n  knownTotalCost       Int?\n  dueDate              DateTime?\n  // P8-13 (tab 09_Dettes): « owed » — what I owe (D-02 to D-05) — or « lent »\n  // — a receivable, what is owed to me (D-01). Always kept apart.\n  direction            String           @default(\"owed\") @db.VarChar(5)\n  // D-01 to D-05, when the person said which kind it is.\n  debtType             String?          @db.VarChar(4)\n  // The budget envelope this debt's monthly instalment is planned in (P8-24): one, in the current budget, kept in step with the instalment.\n  budgetEnvelopeId     String?          @db.VarChar(191)\n  // The account that carries it (P8-13, ARC-04): a receivable (AC-09) or a\n  // loan (AC-08). Lending and repaying are then real transfers.\n  accountId            String?\n  account              FinAccount?      @relation(fields: [accountId], references: [id], onDelete: SetNull)\n  note                 String?          @db.VarChar(300)\n  scope                String           @default(\"personal\") @db.VarChar(20)\n  source               String           @db.VarChar(20)\n  sourceRef            String?          @db.VarChar(200)\n  status               String           @db.VarChar(20)\n  confidence           String?          @db.VarChar(10)\n  consentUses          Json             @default(\"[]\")\n  effectiveAt          DateTime         @default(now())\n  collectedAt          DateTime         @default(now())\n  version              Int              @default(1)\n  archivedAt           DateTime?\n  deletedAt            DateTime?\n  createdAt            DateTime         @default(now())\n  updatedAt            DateTime         @updatedAt\n  payments             FinDebtPayment[]\n\n  @@index([userId, deletedAt])\n  @@map(\"fin_debts\")\n}\n\n// One payment against one debt, so the outstanding principal is a FACT\n// (declared, then paid down) rather than something recomputed from a\n// standalone instalment figure that may have changed since.\nmodel FinDebtPayment {\n  id        String    @id @default(uuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  debtId    String\n  debt      FinDebt   @relation(fields: [debtId], references: [id], onDelete: Cascade)\n  amount    Int\n  currency  String    @db.VarChar(3)\n  paidAt    DateTime\n  note      String?   @db.VarChar(300)\n  createdAt DateTime  @default(now())\n  deletedAt DateTime?\n\n  @@index([debtId])\n  @@index([userId, deletedAt])\n  @@map(\"fin_debt_payments\")\n}\n\n// ---- FINCLUDIA calendar and recurring expenses (P6-07) -----------------------\n// Two tables, and deliberately NOT a third: a planned payment is already a\n// movement marked `planned` in `fin_transactions` (P6-04), so the calendar reads\n// it there. Copying planned events into their own table would be the double\n// counting the client forbids — one row, one reading, « Marquer payé » flips it\n// to real in place.\n\n// A recurring expense or income the person confirmed: a subscription, a rent, a\n// salary. Detection (ALG-04) only ever PROPOSES one; nothing is created without\n// an explicit confirmation, and nothing is ever cancelled on anybody's behalf\n// (« jamais de résiliation automatique » — this table has no notion of\n// terminating a contract, only of no longer tracking it).\nmodel FinRecurrence {\n  id           String          @id @default(uuid())\n  userId       String\n  user         User            @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label        String          @db.VarChar(80)\n  categoryId   String?\n  category     FinCategory?    @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  // \"income\" | \"expense\" (TRANSACTION_KINDS): a recurrence is money that comes\n  // in or goes out, like the movement it will become.\n  kind         String          @db.VarChar(10)\n  value        Int\n  currency     String          @db.VarChar(3)\n  // One of FREQUENCIES (constants/finance.js). F049 normalises it to the month\n  // so the monthly and yearly cost of a subscription can be shown.\n  frequency    String          @db.VarChar(20)\n  // The next date this is expected. Advanced when an occurrence is confirmed;\n  // the calendar projects the following ones from the frequency.\n  nextDate     DateTime\n  endDate      DateTime?\n  // Days BEFORE `nextDate` to remind. The channel is P6-18's; until then this\n  // is read by the interface and pushed nowhere.\n  reminderDays Json            @default(\"[7, 1]\")\n  // Where this row came from: `detected` means ALG-04 proposed it and the\n  // person confirmed it, `manual` means they typed it. Kept apart from the\n  // socle's `source` (which says HOW the value entered) because the client asks\n  // specifically for a detection that is proposed then confirmed.\n  detected     Boolean         @default(false)\n  // P8-11 (tab 08B): the account credited or debited, how an occurrence\n  // becomes real — « confirm » (asked the day it falls, recommended for\n  // income), « auto_real » (recorded as realised on its own), « planned »\n  // (shown as planned until marked paid) — and what to do when the usual day\n  // falls on a weekend (PB-F021's « règle jour »; « previous » working day by\n  // default, the value retained until the client answers question C4).\n  accountId    String?\n  account      FinAccount?     @relation(fields: [accountId], references: [id], onDelete: SetNull)\n  creationMode String          @default(\"confirm\") @db.VarChar(12)\n  weekendRule  String          @default(\"previous\") @db.VarChar(10)\n  occurrences  FinOccurrence[]\n  note         String?         @db.VarChar(300)\n  scope        String          @default(\"personal\") @db.VarChar(20)\n  source       String          @db.VarChar(20)\n  sourceRef    String?         @db.VarChar(200)\n  status       String          @db.VarChar(20)\n  confidence   String?         @db.VarChar(10)\n  consentUses  Json            @default(\"[]\")\n  effectiveAt  DateTime        @default(now())\n  collectedAt  DateTime        @default(now())\n  version      Int             @default(1)\n  archivedAt   DateTime?\n  deletedAt    DateTime?\n  createdAt    DateTime        @default(now())\n  updatedAt    DateTime        @updatedAt\n\n  @@index([userId, nextDate])\n  @@index([categoryId])\n  @@map(\"fin_recurrences\")\n}\n\n// Money set aside month by month for a dated expense: school fees in September,\n// an insurance premium in March (the client's « provisions de dépenses\n// annuelles ou d'études »).\n//\n// A provision NEVER creates a realised expense — the client says so explicitly.\n// `provisioned` is what has been put aside so far, and F045 computes what is\n// left to put aside per month; neither is a movement, and neither enters a\n// total of what was spent.\nmodel FinProvision {\n  id           String       @id @default(uuid())\n  userId       String\n  user         User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label        String       @db.VarChar(80)\n  categoryId   String?\n  category     FinCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  // The amount the dated expense is expected to be.\n  value        Int\n  currency     String       @db.VarChar(3)\n  // What has already been set aside for it.\n  provisioned  Int          @default(0)\n  // The date the expense falls due.\n  targetDate   DateTime\n  reminderDays Json         @default(\"[7, 1]\")\n  note         String?      @db.VarChar(300)\n  scope        String       @default(\"personal\") @db.VarChar(20)\n  source       String       @db.VarChar(20)\n  sourceRef    String?      @db.VarChar(200)\n  status       String       @db.VarChar(20)\n  confidence   String?      @db.VarChar(10)\n  consentUses  Json         @default(\"[]\")\n  effectiveAt  DateTime     @default(now())\n  collectedAt  DateTime     @default(now())\n  version      Int          @default(1)\n  archivedAt   DateTime?\n  deletedAt    DateTime?\n  createdAt    DateTime     @default(now())\n  updatedAt    DateTime     @updatedAt\n\n  @@index([userId, targetDate])\n  @@index([categoryId])\n  @@map(\"fin_provisions\")\n}\n\n// ---- FINCLUDIA real patrimony (P6-11) ----------------------------------------\n// Assets only. The client's screen C16 shows « actifs et passifs », but the\n// liabilities already have their table (`fin_debts`, P6-10) and F035 reads them\n// there: a second table of liabilities would be two places to correct the same\n// debt, and net worth would depend on which one the caller used.\n//\n// The fictional status is FORBIDDEN here — the client's own sentence. The whole\n// point of F035 is that net worth is real, and one fictional row in it makes the\n// figure a lie. Enforced by zod, by a CHECK, and by the consistency control.\nmodel FinAsset {\n  id          String       @id @default(uuid())\n  userId      String\n  user        User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  label       String       @db.VarChar(80)\n  // One of ASSET_KINDS (constants/finWealth.js): the client's own list.\n  kind        String       @db.VarChar(20)\n  categoryId  String?\n  category    FinCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  value       Int\n  currency    String       @db.VarChar(3)\n  // WHEN the value was established. Not `updatedAt`: re-reading a row does not\n  // make its valuation fresher, and the client's « alerte valeur de plus de 90\n  // jours » is measured on this date (F055).\n  valuedAt    DateTime\n  // One of ASSET_LIQUIDITY. F014 (« réserve en mois ») requires the illiquid to\n  // be excluded and the engine cannot tell an account from a flat on its own.\n  liquidity   String       @db.VarChar(20)\n  // Where it is held, as the person wrote it (a bank's name, \"coffre\",\n  // \"maison\"). Free text: the client gives no list, and inventing a closed one\n  // would refuse answers it means to accept.\n  holder      String?      @db.VarChar(80)\n  note        String?      @db.VarChar(300)\n  scope       String       @default(\"personal\") @db.VarChar(20)\n  source      String       @db.VarChar(20)\n  sourceRef   String?      @db.VarChar(200)\n  status      String       @db.VarChar(20)\n  confidence  String?      @db.VarChar(10)\n  consentUses Json         @default(\"[]\")\n  effectiveAt DateTime     @default(now())\n  collectedAt DateTime     @default(now())\n  version     Int          @default(1)\n  archivedAt  DateTime?\n  deletedAt   DateTime?\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  @@index([userId, deletedAt])\n  @@index([userId, valuedAt])\n  @@index([categoryId])\n  @@map(\"fin_assets\")\n}\n\n// ---- FINCLUDIA shared spaces (P6-13) -----------------------------------------\n// The « À plusieurs » hub: a space, its members with their role, what each\n// member chooses to share, and the invitations.\n//\n// The phase rule the whole design serves: « données privées par défaut ; rien\n// n'entre dans un espace partagé sans action explicite ». So sharing is stored\n// PER MEMBER, not per space: joining a space reveals nothing, and each person\n// decides, kind by kind, what the others may see of theirs.\n\nmodel FinSpace {\n  id           String              @id @default(uuid())\n  // One of SPACE_KINDS (constants/finSpace.js): flatshare, couple, household.\n  kind         String              @db.VarChar(20)\n  label        String              @db.VarChar(80)\n  // The currency the space's shared figures are expressed in. One per space:\n  // the engine never converts without a dated rate, so a space that mixed\n  // currencies could not total anything.\n  currency     String              @db.VarChar(3)\n  // Default split rule for shared expenses (SPLIT_RULES). Used by P6-14; set\n  // here because the client asks for it at creation.\n  splitRule    String              @default(\"equal\") @db.VarChar(30)\n  // Below this amount a debt is no longer PROPOSED as a repayment (P9-04, the\n  // client's « petit solde », 200 DA by default, editable). It only hides a\n  // proposal: the balance itself is never erased.\n  smallBalance Int                 @default(20000)\n  // Set when the owner closes a TEMPORARY space (P9-03, rule B3): from then on\n  // nothing is written in it; the history, balances, reports and exports stay readable.\n  closedAt     DateTime?\n  note         String?             @db.VarChar(300)\n  // The space is not itself a financial datum — it holds no amount — but it\n  // carries the socle's traceability columns, because who created it and when\n  // is part of the trail of every figure computed inside it.\n  source       String              @db.VarChar(20)\n  status       String              @db.VarChar(20)\n  version      Int                 @default(1)\n  archivedAt   DateTime?\n  deletedAt    DateTime?\n  createdAt    DateTime            @default(now())\n  updatedAt    DateTime            @updatedAt\n  members      FinSpaceMember[]\n  invitations  FinSpaceInvite[]\n  expenses     FinSharedExpense[]\n  budgets      FinSpaceBudget[]\n  tasks        FinSpaceTask[]\n  inflows      FinSpaceInflow[]\n  settlements  FinSettlement[]\n  goals        FinSpaceGoal[]\n  children     FinChild[]\n  provisions   FinSpaceProvision[]\n\n  @@index([kind])\n  @@map(\"fin_spaces\")\n}\n\n// One person in one space, with their role and what THEY share.\n//\n// `onDelete: Cascade` on both sides: a space that goes takes its memberships,\n// and an account that is erased leaves none behind — the complete deletion the\n// privacy text promises (P6-01 point 9).\nmodel FinSpaceMember {\n  id                  String                     @id @default(uuid())\n  spaceId             String\n  space               FinSpace                   @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  userId              String\n  user                User                       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  // One of SPACE_ROLES: owner, admin, member, viewer.\n  role                String                     @db.VarChar(20)\n  // What this member shares with the others, per data kind (SHAREABLE_KINDS),\n  // at one of SHARING_LEVELS. The default is every kind `private`, and it is\n  // the member — never an admin — who changes it.\n  sharing             Json                       @default(\"{}\")\n  // The name the others see. Separate from the account's own name on purpose:\n  // joining a flatshare should not hand over one's legal name.\n  displayName         String?                    @db.VarChar(60)\n  joinedAt            DateTime                   @default(now())\n  leftAt              DateTime?\n  paidExpenses        FinSharedExpense[]         @relation(\"ExpensePayer\")\n  recordedExpenses    FinSharedExpense[]         @relation(\"ExpenseRecorder\")\n  shares              FinSharedShare[]\n  settlementsFrom     FinSettlement[]            @relation(\"SettlementFrom\")\n  settlementsTo       FinSettlement[]            @relation(\"SettlementTo\")\n  recordedSettlements FinSettlement[]            @relation(\"SettlementRecorder\")\n  goalContributions   FinSpaceGoalContribution[]\n  goalShares          FinSpaceGoalShare[]\n  createdAt           DateTime                   @default(now())\n  updatedAt           DateTime                   @updatedAt\n\n  // One membership per person per space. A second one would make \"my role\" a\n  // question with two answers.\n  @@unique([spaceId, userId])\n  @@index([userId])\n  @@map(\"fin_space_members\")\n}\n\n// An invitation to join a space. The token is the secret; it is stored HASHED,\n// like a session or a password-reset token, so a leaked database does not hand\n// over the ability to join somebody's household.\nmodel FinSpaceInvite {\n  id           String    @id @default(uuid())\n  spaceId      String\n  space        FinSpace  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  // Who sent it. Kept to show « invité par » and to refuse an invitation from\n  // somebody who has since lost the right to invite.\n  invitedById  String\n  invitedBy    User      @relation(\"SpaceInviteSender\", fields: [invitedById], references: [id], onDelete: Cascade)\n  // SHA-256 of the token handed out. The plain token exists only in the link.\n  tokenHash    String    @unique @db.VarChar(64)\n  // The role the invitee will get. Never `owner`: a space has exactly one, and\n  // it is not something an invitation can grant.\n  role         String    @db.VarChar(20)\n  // One of INVITE_STATUSES.\n  status       String    @default(\"pending\") @db.VarChar(20)\n  expiresAt    DateTime\n  acceptedAt   DateTime?\n  acceptedById String?\n  acceptedBy   User?     @relation(\"SpaceInviteAcceptor\", fields: [acceptedById], references: [id], onDelete: SetNull)\n  createdAt    DateTime  @default(now())\n\n  @@index([spaceId, status])\n  @@map(\"fin_space_invites\")\n}\n\n// ---- FINCLUDIA paper portfolio (P6-12) ---------------------------------------\n// Fictional from end to end: « badge SIMULATION permanent, aucune exécution,\n// aucune valeur fictive dans le patrimoine réel ». P6-11 forbids the reverse\n// too, so the two can never meet.\n//\n// There is no instrument catalogue and no price table, because the client has\n// supplied neither and its own rule for this task forbids inventing them\n// (« uniquement des données fournies ou validées par le client »). The person\n// names the instrument and states the simulated price themselves — their own\n// simulation, not reference data the platform publishes.\n\nmodel FinPaperPortfolio {\n  id          String               @id @default(uuid())\n  // One per account: « le portefeuille fictif », and « réinitialisation » means\n  // starting this one over rather than keeping a drawer of them.\n  userId      String               @unique\n  user        User                 @relation(fields: [userId], references: [id], onDelete: Cascade)\n  // The fictional starting capital. The client's own default is 100 000 DA,\n  // and it is « modifiable ».\n  capital     Int\n  // Fictional cash not currently invested. Kept as a column rather than derived\n  // from the trades: it is what the next buy is checked against, and deriving\n  // it on every write would make that check a race.\n  cash        Int\n  currency    String               @db.VarChar(3)\n  // Simulated fee rate, as a decimal of the traded amount. Stored per portfolio\n  // so it is visible and editable — never a hidden coefficient.\n  feeRate     Float                @default(0.01)\n  // When the portfolio was last reset, so the figures can say what period they\n  // describe.\n  resetAt     DateTime             @default(now())\n  // The socle's traceability columns. `status` is always `fictional` here, and\n  // a CHECK says so: that is what keeps this table out of every real total.\n  source      String               @db.VarChar(20)\n  status      String               @db.VarChar(20)\n  version     Int                  @default(1)\n  createdAt   DateTime             @default(now())\n  updatedAt   DateTime             @updatedAt\n  instruments FinPaperInstrument[]\n  trades      FinPaperTrade[]\n\n  @@map(\"fin_paper_portfolios\")\n}\n\n// An instrument the person chose to practise with, and the simulated price THEY\n// stated. `markedAt` dates that price, exactly as a real asset's valuation is\n// dated in P6-11: a price nobody can date is a price nobody can check.\nmodel FinPaperInstrument {\n  id          String            @id @default(uuid())\n  portfolioId String\n  portfolio   FinPaperPortfolio @relation(fields: [portfolioId], references: [id], onDelete: Cascade)\n  // Free text: see the note above. The day the client supplies a catalogue,\n  // this becomes a key into it.\n  label       String            @db.VarChar(80)\n  // The person's own simulated price per unit, in centimes.\n  markPrice   Int\n  markedAt    DateTime\n  note        String?           @db.VarChar(300)\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n  trades      FinPaperTrade[]\n\n  // One row per instrument in a portfolio: two would split the same position.\n  @@unique([portfolioId, label])\n  @@map(\"fin_paper_instruments\")\n}\n\n// One fictional decision. This table IS the client's « journal de décisions »:\n// what was done, at what simulated price, with what fee — and `note`, which is\n// WHY. The reason is the point of the journal; the amounts are the easy part.\nmodel FinPaperTrade {\n  id           String             @id @default(uuid())\n  portfolioId  String\n  portfolio    FinPaperPortfolio  @relation(fields: [portfolioId], references: [id], onDelete: Cascade)\n  instrumentId String\n  instrument   FinPaperInstrument @relation(fields: [instrumentId], references: [id], onDelete: Cascade)\n  // \"buy\" | \"sell\" (PAPER_TRADE_KINDS). Nothing else: there is no execution,\n  // no order type, no leverage and no short.\n  kind         String             @db.VarChar(10)\n  // Whole units. A workshop does not need fractional shares, and an integer is\n  // a quantity somebody can check.\n  quantity     Int\n  unitPrice    Int\n  // The simulated fee actually applied, stored rather than recomputed: a later\n  // change of the portfolio's rate must not rewrite the past.\n  fee          Int\n  currency     String             @db.VarChar(3)\n  decidedAt    DateTime\n  note         String?            @db.VarChar(300)\n  status       String             @db.VarChar(20)\n  createdAt    DateTime           @default(now())\n\n  @@index([portfolioId, decidedAt])\n  @@index([instrumentId])\n  @@map(\"fin_paper_trades\")\n}\n\n// ---- FINCLUDIA shared expenses and settlements (P6-14) -----------------------\n// Screens P02 and P03, F041 / F042 / F043 and ALG-02.\n//\n// Everything lives inside a shared space (P6-13), in that space's currency: the\n// engine never converts without a dated rate, so a space that mixed currencies\n// could not total anything.\n//\n// A settlement is DECLARATIVE. Nothing in FINCLUDIA moves money — the client is\n// explicit about it — so this table records what people say they have settled\n// between themselves, and nothing else.\n\nmodel FinSharedExpense {\n  id                    String           @id @default(uuid())\n  spaceId               String\n  space                 FinSpace         @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  // Who paid. A MEMBERSHIP, not a user: the expense belongs to the space, and\n  // a member who later leaves must still be readable as the payer of a past\n  // expense (their membership row survives with `leftAt` set).\n  payerId               String\n  payer                 FinSpaceMember   @relation(\"ExpensePayer\", fields: [payerId], references: [id], onDelete: Cascade)\n  label                 String           @db.VarChar(80)\n  value                 Int\n  currency              String           @db.VarChar(3)\n  occurredAt            DateTime\n  // One of SPLIT_MODES (constants/finShared.js). Stored so the screen can say\n  // HOW it was divided, and so a correction can redo the same kind of split.\n  splitMode             String           @db.VarChar(30)\n  // The category of the client's own reference, when the person chose one.\n  categoryId            String?\n  category              FinCategory?     @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  note                  String?          @db.VarChar(300)\n  // « réalisée / prévue / annulée » (P9-04). Only a `done` expense counts in\n  // the balances; a cancelled one stays readable, with its trace.\n  lifecycle             String           @default(\"done\") @db.VarChar(12)\n  cancelledAt           DateTime?\n  // The free unit of a split by usage (« kWh », « nuits »): one per expense.\n  usageUnit             String?          @db.VarChar(30)\n  // One of the 19 collective categories (COLC-nn, constants/finCollectiveCategories.js):\n  // what the common budget of the space reads (P9-05).\n  collectiveCategory    String?          @db.VarChar(8)\n  // The ONE personal transaction this expense is paid from (P9-08, COL-F13,\n  // B5): unique, so 1 collective expense <-> 0 or 1 personal transaction. Only\n  // its payer can see it.\n  // An optional, free label inside the category, THIS space's own (P9-14): the workbook gives no list.\n  subCategory           String?          @db.VarChar(40)\n  // The receipt of this expense, if any.\n  receipt               Media?           @relation(\"SharedExpenseReceipt\")\n  // P9-15: what the payer's own money did. The transfer of the part that is not\n  // theirs towards their receivable account (the pair's id), the amount of their\n  // existing transaction before it was cut to their share, and whether the\n  // personal expense was made BY this record (then it goes back with it).\n  advanceTransferId     String?          @db.VarChar(36)\n  advanceOriginalValue  Int?\n  personalCreated       Boolean          @default(false)\n  personalTransactionId String?          @unique\n  personalTransaction   FinTransaction?  @relation(\"SharedExpenseSource\", fields: [personalTransactionId], references: [id], onDelete: SetNull)\n  // Who recorded it, which is not always the payer: a flatmate may enter the\n  // rent somebody else paid.\n  recordedById          String\n  recordedBy            FinSpaceMember   @relation(\"ExpenseRecorder\", fields: [recordedById], references: [id], onDelete: Cascade)\n  source                String           @db.VarChar(20)\n  status                String           @db.VarChar(20)\n  version               Int              @default(1)\n  deletedAt             DateTime?\n  createdAt             DateTime         @default(now())\n  updatedAt             DateTime         @updatedAt\n  shares                FinSharedShare[]\n\n  @@index([spaceId, occurredAt])\n  @@index([payerId])\n  @@index([categoryId])\n  @@map(\"fin_shared_expenses\")\n}\n\n// One participant's share of one expense.\n//\n// The shares of an expense add up to its amount EXACTLY — the client states it\n// as a rule, and it is checked by the service and by the consistency control.\n// The payer may have no share at all (« payeur pouvant ne pas participer »),\n// which is why this is a separate table rather than a column on the expense.\nmodel FinSharedShare {\n  id        String           @id @default(uuid())\n  expenseId String\n  expense   FinSharedExpense @relation(fields: [expenseId], references: [id], onDelete: Cascade)\n  memberId  String\n  member    FinSpaceMember   @relation(fields: [memberId], references: [id], onDelete: Cascade)\n  // What this participant owes of the expense, in centimes.\n  share     Int\n  // The weight that produced it, when the split was proportional: a percentage\n  // in hundredths of a percent, or the income used. Kept so the screen can\n  // show WHY a share is what it is, and so the figure can be argued with.\n  weight    Int?\n  createdAt DateTime         @default(now())\n\n  // One share per participant per expense: two would split the same money\n  // twice and break the \"shares add up to the amount\" rule silently.\n  @@unique([expenseId, memberId])\n  @@index([memberId])\n  @@map(\"fin_shared_shares\")\n}\n\n// A settlement one member declares having made to another. DECLARATIVE ONLY:\n// no payment integration, and nothing here moves any money.\nmodel FinSettlement {\n  id           String         @id @default(uuid())\n  spaceId      String\n  space        FinSpace       @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  fromId       String\n  from         FinSpaceMember @relation(\"SettlementFrom\", fields: [fromId], references: [id], onDelete: Cascade)\n  toId         String\n  to           FinSpaceMember @relation(\"SettlementTo\", fields: [toId], references: [id], onDelete: Cascade)\n  value        Int\n  currency     String         @db.VarChar(3)\n  settledAt    DateTime\n  note         String?        @db.VarChar(300)\n  // Who declared it. Either side may: the one who paid, or the one who was\n  // paid. The trail says which, because a settlement nobody can attribute is\n  // a settlement nobody can dispute.\n  recordedById String\n  recordedBy   FinSpaceMember @relation(\"SettlementRecorder\", fields: [recordedById], references: [id], onDelete: Cascade)\n  // P9-15: the transfer from the receivable account to the account that received the money, when the receiver said where it arrived.\n  transferId   String?        @db.VarChar(36)\n  source       String         @db.VarChar(20)\n  status       String         @db.VarChar(20)\n  deletedAt    DateTime?\n  createdAt    DateTime       @default(now())\n\n  @@index([spaceId, settledAt])\n  @@index([fromId])\n  @@index([toId])\n  @@map(\"fin_settlements\")\n}\n\n// ---- Shared goals, children and provisions (P6-15) ---------------------------\n// Colocation, couple, family: screens P05, CO02-CO06, CP02-CP04, FA02-FA06.\n//\n// A common goal or envelope belongs to the SPACE, not to one account — unlike\n// `FinGoal` (P6-08), which is personal. That is the point: everyone who is a\n// member sees it by construction, the same way a shared expense (P6-14)\n// already does, rather than through the permission matrix (P6-13), which only\n// ever governs PERSONAL data someone chooses to reveal.\n\nmodel FinSpaceGoal {\n  id                      String                     @id @default(uuid())\n  spaceId                 String\n  space                   FinSpace                   @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  label                   String                     @db.VarChar(80)\n  target                  Int\n  currency                String                     @db.VarChar(3)\n  targetDate              DateTime?\n  note                    String?                    @db.VarChar(300)\n  version                 Int                        @default(1)\n  archivedAt              DateTime?\n  deletedAt               DateTime?\n  createdAt               DateTime                   @default(now())\n  updatedAt               DateTime                   @updatedAt\n  // P9-17: the calendar of contributions. Every `contributionEveryMonths` months\n  // from `firstDueAt`, each member owes the share set for them below. Without it\n  // there is no due date, hence no delay to measure (only milestones).\n  contributionEveryMonths Int?\n  firstDueAt              DateTime?\n  contributions           FinSpaceGoalContribution[]\n  shares                  FinSpaceGoalShare[]\n\n  @@index([spaceId, deletedAt])\n  @@map(\"fin_space_goals\")\n}\n\n// What one member actually put in — the FACT a common goal's progress is\n// built from, rather than a single editable \"allocated\" number nobody can\n// attribute (unlike a personal goal, several people pay into this one).\nmodel FinSpaceGoalContribution {\n  id            String         @id @default(uuid())\n  spaceGoalId   String\n  spaceGoal     FinSpaceGoal   @relation(fields: [spaceGoalId], references: [id], onDelete: Cascade)\n  memberId      String\n  member        FinSpaceMember @relation(fields: [memberId], references: [id], onDelete: Cascade)\n  amount        Int\n  currency      String         @db.VarChar(3)\n  contributedAt DateTime\n  note          String?        @db.VarChar(300)\n  createdAt     DateTime       @default(now())\n  deletedAt     DateTime?\n\n  @@index([spaceGoalId])\n  @@index([memberId])\n  @@map(\"fin_space_goal_contributions\")\n}\n\n// What one member is expected to put in at each due date of a common goal (P9-17).\nmodel FinSpaceGoalShare {\n  id          String         @id @default(uuid())\n  spaceGoalId String\n  spaceGoal   FinSpaceGoal   @relation(fields: [spaceGoalId], references: [id], onDelete: Cascade)\n  memberId    String\n  member      FinSpaceMember @relation(fields: [memberId], references: [id], onDelete: Cascade)\n  amount      Int\n\n  @@unique([spaceGoalId, memberId])\n  @@index([memberId])\n  @@map(\"fin_space_goal_shares\")\n}\n\n// A household's child (P6-15, famille): MINIMAL data on purpose — a first\n// name and a birth year, never a full birth date, never a national id or\n// anything that identifies the child outside this one household's planning.\nmodel FinChild {\n  id         String    @id @default(uuid())\n  spaceId    String\n  space      FinSpace  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  firstName  String    @db.VarChar(60)\n  birthYear  Int\n  note       String?   @db.VarChar(300)\n  archivedAt DateTime?\n  deletedAt  DateTime?\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  @@index([spaceId, deletedAt])\n  @@map(\"fin_children\")\n}\n\n// A household's annual or irregular expense, provisioned month by month\n// (F045): school fees, an insurance renewal, a family trip. `alreadyProvisioned`\n// is corrected as the household sets money aside; it is never recomputed from\n// elsewhere, because nothing else in FINCLUDIA tracks it.\nmodel FinSpaceProvision {\n  id                 String    @id @default(uuid())\n  spaceId            String\n  space              FinSpace  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  label              String    @db.VarChar(80)\n  plannedAmount      Int\n  alreadyProvisioned Int       @default(0)\n  currency           String    @db.VarChar(3)\n  targetDate         DateTime\n  note               String?   @db.VarChar(300)\n  version            Int       @default(1)\n  archivedAt         DateTime?\n  deletedAt          DateTime?\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  @@index([spaceId, deletedAt])\n  @@map(\"fin_space_provisions\")\n}\n\n// ---- Notifications (P6-18), screen C24 ---------------------------------------\n// In-app only for now: « canal in-app d'abord ; e-mail / push selon P6-01 » —\n// the client's own order, and e-mail/push are a reserve exactly like every\n// other P6-01 placeholder in this schema.\n//\n// `type` is a closed catalogue (constants/finNotification.js), never free\n// text: the server decides what a notification says, through i18n keys and\n// `params`, so nothing typed by anyone ends up rendered as a notification.\nmodel FinNotification {\n  id          String    @id @default(uuid())\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  type        String    @db.VarChar(40)\n  // The client's three filters: action / information / sécurité.\n  category    String    @db.VarChar(20)\n  // The client's own ordering for competing alerts: sécurité > échéance >\n  // budget > apprentissage (ACTION_PRIORITIES, shared with the home\n  // dashboard's action list, P6-06) — a SORT key, not the filter above.\n  priority    String    @db.VarChar(20)\n  // i18n interpolation values for this notification's text (amounts, labels,\n  // ids already safe to show back to their own owner) — never a rendered\n  // sentence, so the text stays translated like everything else.\n  params      Json      @default(\"{}\")\n  // Where the client's own « lien vers l'écran concerné » leads. Always a\n  // path this server itself constructs, never user input.\n  link        String?   @db.VarChar(200)\n  // What this notification is ABOUT (a budget, an envelope, a goal...), for\n  // the anti-repetition rule: created once per (type, referenceId) at a given\n  // signal, never once per read.\n  referenceId String?   @db.VarChar(191)\n  read        Boolean   @default(false)\n  readAt      DateTime?\n  createdAt   DateTime  @default(now())\n\n  @@index([userId, read, createdAt])\n  @@index([userId, type, referenceId])\n  @@map(\"fin_notifications\")\n}\n\n// ---- \"Apprendre\" glossary and mini-guides (P2-08) -----------------------------\n// Both are written by an administrator (rule: nothing financial, legal or\n// tariff-specific is invented — only general definitions), in one language,\n// like articles and formations.\nmodel GlossaryTerm {\n  id           String   @id @default(uuid())\n  slug         String   @unique\n  term         String   @db.VarChar(120)\n  definition   String   @db.Text\n  example      String?  @db.Text\n  // Slugs of other terms (closed set: validated against existing terms).\n  // Key of a simulator (constants/simulators.js) this entry sends to, for the\n  // client's \"Simuler\" button (C21). An ADMINISTRATOR picks it and the server\n  // validates it against the registry: guessing it from the wording would send\n  // people to the wrong calculator.\n  simulatorKey String?  @db.VarChar(60)\n  relatedTerms Json     @default(\"[]\")\n  // \"beginner\" | \"intermediate\" | \"advanced\", nullable (not every term needs one).\n  level        String?\n  theme        String?  @db.VarChar(60)\n  status       String   @default(\"draft\")\n  language     String   @default(\"fr\")\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  revisions GlossaryTermRevision[]\n\n  @@map(\"glossary_terms\")\n}\n\n// A snapshot taken right before a term's definition changes (the client\n// requires a history: \"une définition remplacée garde son historique\"),\n// exactly the pattern already used for lessons (LessonRevision).\nmodel GlossaryTermRevision {\n  id         String       @id @default(uuid())\n  termId     String\n  term       GlossaryTerm @relation(fields: [termId], references: [id], onDelete: Cascade)\n  definition String       @db.Text\n  example    String?      @db.Text\n  createdAt  DateTime     @default(now())\n\n  @@index([termId, createdAt])\n  @@map(\"glossary_term_revisions\")\n}\n\nmodel MiniGuide {\n  id           String   @id @default(uuid())\n  slug         String   @unique\n  title        String   @db.VarChar(150)\n  // Sanitised rich text (sanitizeRichText), same allow-list as articles/lessons.\n  body         String   @db.MediumText\n  level        String?\n  theme        String?  @db.VarChar(60)\n  // Key of a simulator (constants/simulators.js) this entry sends to, for the\n  // client's \"Simuler\" button (C21). An ADMINISTRATOR picks it and the server\n  // validates it against the registry: guessing it from the wording would send\n  // people to the wrong calculator.\n  simulatorKey String?  @db.VarChar(60)\n  status       String   @default(\"draft\")\n  language     String   @default(\"fr\")\n  position     Int      @default(0)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@map(\"mini_guides\")\n}\n\n// ---- FINCLUDIA deterministic assistant (P3-19) ---------------------------------\n// Closed catalogue of intentions, taken as-is from the client's own file\n// (FINCLUDIA_Cahier_des_Charges_Complet.xlsx, onglet \"13_Chatbot\"): the 8 codes,\n// their example phrasing and their allowed answer are the client's, not invented.\nmodel FinIntent {\n  id               String   @id @default(uuid())\n  // NAVIGUER | EXPLIQUER_INDICATEUR | CRÉER_OBJECTIF | AIDE_BUDGET | AIDE_DETTE |\n  // APPRENDRE_TERME | CHERCHER_SOLUTION | DÉPENSE_PARTAGÉE (the client's closed list).\n  code             String   @unique @db.VarChar(40)\n  label            String   @db.VarChar(120)\n  exampleQuery     String   @db.VarChar(200)\n  // Keywords/synonyms the resolver matches against (admin-editable, P3-19 \"Résolveur\n  // d'intentions\": \"mots-clés, synonymes et contexte écran\").\n  keywords         Json     @default(\"[]\")\n  // Sanitised rich text, pre-written (never generated): \"Moteur de modèles\" in the\n  // client's words — \"textes pré-écrits avec variables provenant des API.\" No\n  // variable is substituted yet (the financial-profile APIs it would read from,\n  // P6-02, do not exist until P6-01 is answered); the text itself must stand on\n  // its own until then.\n  responseTemplate String   @db.Text\n  // A path of this SITE the intent can open (\"Liens profonds\"), or null when the\n  // client's own target screen (C07, C14, P03...) is not built yet — the resolver\n  // then shows a \"not available yet\" message instead of a dead or wrong link.\n  deepLinkPath     String?  @db.VarChar(200)\n  status           String   @default(\"draft\")\n  position         Int      @default(0)\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@map(\"fin_intents\")\n}\n\n// \"Moteur de parcours\" — a state machine: parcours_id / étape_id / réponses\n// possibles / étape_suivante, in the client's own words.\nmodel FinFlow {\n  id        String        @id @default(uuid())\n  key       String        @unique @db.VarChar(60)\n  name      String        @db.VarChar(150)\n  status    String        @default(\"draft\")\n  createdAt DateTime      @default(now())\n  updatedAt DateTime      @updatedAt\n  steps     FinFlowStep[]\n\n  @@map(\"fin_flows\")\n}\n\nmodel FinFlowStep {\n  id        String   @id @default(uuid())\n  flowId    String\n  flow      FinFlow  @relation(fields: [flowId], references: [id], onDelete: Cascade)\n  stepKey   String   @db.VarChar(60)\n  prompt    String   @db.Text\n  // [{ label, nextStepKey | null (ends the flow), intentCode | null }]\n  options   Json     @default(\"[]\")\n  position  Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([flowId, stepKey])\n  @@map(\"fin_flow_steps\")\n}\n\n// \"Audit\": intention, parcours, version du modèle, action cliquée, erreur —\n// in the client's words, \"sans donnée financière en clair\": only codes are kept,\n// never the free text the visitor typed nor any amount.\nmodel FinAuditLog {\n  id         String   @id @default(uuid())\n  userId     String?\n  user       User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  intentCode String?  @db.VarChar(40)\n  flowKey    String?  @db.VarChar(60)\n  stepKey    String?  @db.VarChar(60)\n  // resolved | fallback | deep_link_opened | flow_started | flow_step | flow_ended | not_available\n  action     String   @db.VarChar(30)\n  createdAt  DateTime @default(now())\n\n  @@index([createdAt])\n  @@map(\"fin_audit_logs\")\n}\n\n// Guided assistant (P3-07): a question the visitor picks from a list and the\n// answer shown for it. No free text, no AI: an administrator writes both. One\n// language per entry, like articles; the public API only returns published\n// entries of the visitor's language, in the administrator's order.\nmodel ChatbotEntry {\n  id        String   @id @default(uuid())\n  question  String   @db.VarChar(200)\n  // Sanitised rich text (sanitizeRichText), never raw HTML from the browser.\n  answer    String   @db.Text\n  language  String   @default(\"fr\") @db.VarChar(2)\n  status    String   @default(\"draft\") @db.VarChar(20)\n  position  Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([language, status, position])\n  @@map(\"chatbot_entries\")\n}\n\n// Messages sent through the public contact form (P1-07). Stored in the DB\n// because no email provider is defined yet; an admin view/notification comes\n// later. Only what the form needs: no IP or other personal data is kept.\nmodel ContactMessage {\n  id        String   @id @default(uuid())\n  name      String\n  email     String   @db.VarChar(254)\n  message   String   @db.Text\n  createdAt DateTime @default(now())\n\n  @@map(\"contact_messages\")\n}\n\n// Account categories offered at registration (P3-15). A real table, not a\n// hardcoded list: an administrator can add, rename, reorder or deactivate a\n// category from the admin panel, without a code change or a migration. Kept\n// as a soft reference from `User.accountType` (a plain string, unchanged\n// since P1-06) rather than a foreign key: it is validated against this table\n// at the application layer, exactly like the free-form status fields\n// elsewhere in this schema, so no existing relation, index or test fixture\n// had to move.\nmodel AccountType {\n  id        String   @id @default(uuid())\n  slug      String   @unique\n  label     String\n  isActive  Boolean  @default(true)\n  order     Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"account_types\")\n}\n\n// Small set of platform-wide switches an administrator can change without a\n// deployment (P3-16): maintenance mode, public contact details, and any\n// future key the admin panel adds. Free-form key/value on purpose: adding a\n// new setting never needs a migration.\nmodel PlatformSetting {\n  key       String   @id\n  value     String   @db.Text\n  updatedAt DateTime @updatedAt\n\n  @@map(\"platform_settings\")\n}\n\n// ---------------------------------------------------------------------------\n// E-Learning (P2-01)\n//\n// Conventions, same as User:\n// - Status-like fields are plain strings validated in the application layer\n//   (constants in src/constants/elearning.js) AND guarded by CHECK constraints\n//   added by hand in the migration, so no code path can store an invalid value.\n// - Only the model lives here. Endpoints belong to P2-02 (admin) and\n//   P2-03/P2-04 (learner), media handling to P2-06.\n// ---------------------------------------------------------------------------\n\nmodel FormationCategory {\n  id        String   @id @default(uuid())\n  slug      String   @unique\n  name      String\n  createdAt DateTime @default(now())\n\n  formations Formation[]\n\n  @@map(\"formation_categories\")\n}\n\n// A training programme made of an ordered list of courses.\n// The number of courses is NOT stored: it is count(courses), so it can never\n// disagree with the real list (P2-02 \"définir le nombre de cours\").\nmodel Formation {\n  id                  String @id @default(uuid())\n  slug                String @unique\n  title               String\n  description         String @db.Text\n  // \"draft\" | \"published\". Only published formations are visible to learners.\n  status              String @default(\"draft\")\n  // \"standard\" | \"premium\": lowest access level allowed to enrol.\n  // Checked server-side, never only in the UI (TASKS.md rule 1).\n  requiredAccessLevel String @default(\"standard\")\n  // Account types this formation is suggested to first (client request: a\n  // simple suggestion by account type, never a computed score). Empty = no\n  // particular order. Same JSON-array shape as Article.targetAccountTypes,\n  // same reason: no array column type on MySQL/MariaDB.\n  targetAccountTypes  Json   @default(\"[]\")\n  // The educational profiles it is recommended to (P8-17: LYC, ETU, JAC, SAL,\n  // EPG, AUT). Empty = for everyone. A recommendation, never a restriction.\n  educationProfiles   Json   @default(\"[]\")\n\n  categoryId String?\n  category   FormationCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n\n  coverImageId String? @unique\n  coverImage   Media?  @relation(\"FormationCover\", fields: [coverImageId], references: [id], onDelete: SetNull)\n\n  // Certification information (P2-02 / P2-05).\n  certificationEnabled     Boolean @default(true)\n  certificationTitle       String?\n  certificationDescription String? @db.Text\n\n  // Pedagogical presentation (P3-11). The total duration is NOT stored: it is the sum\n  // of the lessons' estimated minutes, so it can never disagree with the real plan.\n  subtitle      String?\n  // \"beginner\" | \"intermediate\" | \"advanced\" (CHECK in the migration), null = not set.\n  level         String?\n  // Teaching theme, same free-form vocabulary as the glossary (P2-08): the\n  // \"Apprendre\" search filters courses, articles, terms and guides on the\n  // same two axes, so the column has to exist on all four.\n  theme         String? @db.VarChar(60)\n  // MySQL/MariaDB has no array column type: stored as a JSON array (still a\n  // plain JS array end to end, Prisma (de)serialises it automatically).\n  objectives    Json    @default(\"[]\")\n  prerequisites Json    @default(\"[]\")\n\n  createdById String?\n  createdBy   User?   @relation(fields: [createdById], references: [id], onDelete: SetNull)\n\n  publishedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  courses     Course[]\n  sections    Section[]\n  enrollments Enrollment[]\n\n  // Quizzes of the formation (P3-13); `finalQuiz` is the one at the end of the formation.\n  quizzes   Quiz[] @relation(\"FormationQuizzes\")\n  finalQuiz Quiz?  @relation(\"FinalQuiz\")\n\n  @@index([status])\n  @@map(\"formations\")\n}\n\n// One lesson of a formation.\nmodel Course {\n  id          String    @id @default(uuid())\n  formationId String\n  formation   Formation @relation(fields: [formationId], references: [id], onDelete: Cascade)\n\n  title            String\n  summary          String?  @db.Text\n  // Text content of the lesson. Videos / documents are Media rows.\n  body             String?  @db.MediumText\n  // Display order inside the formation (0-based). Not unique on purpose: a\n  // unique constraint makes reordering (swap) fail mid-transaction; the\n  // service reorders in one transaction and lists by (position, createdAt).\n  position         Int\n  // Required courses must all be completed to finish the formation (P2-04).\n  isRequired       Boolean  @default(true)\n  estimatedMinutes Int?\n  // Chapter of the lesson (P3-11). COMPOSITE foreign key (sectionId, formationId) ->\n  // sections(id, formationId): a lesson can never sit in a chapter of another formation, and\n  // a chapter that still holds lessons cannot be deleted (RESTRICT). `position` stays the\n  // GLOBAL order of the lessons inside the formation (chapters first, then the order in the\n  // chapter): the learner side and the progress code keep reading it unchanged.\n  sectionId        String?\n  section          Section? @relation(fields: [sectionId, formationId], references: [id, formationId], onDelete: Restrict)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  media     Media[]\n  progress  CourseProgress[]\n  blocks    LessonBlock[]\n  revisions LessonRevision[]\n  quizzes   Quiz[]\n\n  // Target of the composite foreign key from CourseProgress: guarantees a\n  // progress row can only point to a course of the SAME formation as its\n  // enrollment.\n  @@unique([id, formationId])\n  @@index([formationId, position])\n  @@map(\"courses\")\n}\n\n// A file (video, image, document). The file itself lives in PRIVATE storage:\n// storageKey is an internal key, it must never be serialised to a client or\n// used as a public URL (TASKS.md rule 4, P2-06 signed/temporary access).\nmodel Media {\n  id           String @id @default(uuid())\n  // \"video\" | \"image\" | \"document\"\n  kind         String\n  storageKey   String @unique\n  originalName String @db.VarChar(255)\n  mimeType     String\n  sizeBytes    Int\n\n  courseId String?\n  course   Course? @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  uploadedById String?\n  uploadedBy   User?   @relation(fields: [uploadedById], references: [id], onDelete: SetNull)\n\n  createdAt DateTime @default(now())\n\n  coverOf Formation? @relation(\"FormationCover\")\n\n  // Blog (P3-01): a file attached to an article, or the cover of an article.\n  // A file belongs to at most one lesson OR one article (CHECK in the migration).\n  articleId      String?\n  article        Article? @relation(\"ArticleMedia\", fields: [articleId], references: [id], onDelete: Cascade)\n  articleCoverOf Article? @relation(\"ArticleCover\")\n\n  // Blocks of a lesson that show this file (P3-12). Deleting the file deletes those blocks.\n  blocks LessonBlock[]\n\n  // Receipt of a movement (P6-04, \"justificatif optionnel\"). Private storage\n  // like every other file here, served only to its owner: there is no public\n  // URL for a receipt, ever.\n  //\n  // The key is on THIS side, like courseId and articleId above, so the file row\n  // dies with the movement it documents — and therefore with the account, which\n  // is what the privacy text promises (P6-01 point 9). With the key on the\n  // transaction instead, erasing an account left every receipt behind.\n  finTransactionId String?         @unique\n  finTransaction   FinTransaction? @relation(\"TransactionReceipt\", fields: [finTransactionId], references: [id], onDelete: Cascade)\n\n  // The receipt of a SHARED expense (P9-14): private storage, readable by the members of the space only,\n  // and gone with the expense it documents. Never a public URL.\n  sharedExpenseId String?           @unique\n  sharedExpense   FinSharedExpense? @relation(\"SharedExpenseReceipt\", fields: [sharedExpenseId], references: [id], onDelete: Cascade)\n\n  // Target of the composite foreign key from lesson_blocks: a block can only show a file\n  // that belongs to ITS OWN lesson.\n  @@unique([id, courseId])\n  @@index([courseId])\n  @@index([articleId])\n  @@map(\"media\")\n}\n\n// A user's enrolment in a formation. One per (user, formation).\nmodel Enrollment {\n  id          String    @id @default(uuid())\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  // Restrict: a formation that has learners cannot be deleted (and their\n  // certificates lost); unpublish it instead.\n  formationId String\n  formation   Formation @relation(fields: [formationId], references: [id], onDelete: Restrict)\n\n  // \"active\" | \"completed\"\n  status      String    @default(\"active\")\n  enrolledAt  DateTime  @default(now())\n  completedAt DateTime?\n\n  courseProgress CourseProgress[]\n  certification  Certification?\n  quizAttempts   QuizAttempt[]\n\n  @@unique([userId, formationId])\n  @@unique([id, formationId])\n  @@index([formationId])\n  @@map(\"enrollments\")\n}\n\n// Progress of one enrolment on one course.\n// formationId is stored on purpose: the two composite foreign keys below make\n// the database itself reject a progress row whose course is not part of the\n// enrolled formation (P2-04 \"empêcher une validation incohérente\").\nmodel CourseProgress {\n  id           String @id @default(uuid())\n  enrollmentId String\n  courseId     String\n  formationId  String\n\n  enrollment Enrollment @relation(fields: [enrollmentId, formationId], references: [id, formationId], onDelete: Cascade)\n  course     Course     @relation(fields: [courseId, formationId], references: [id, formationId], onDelete: Cascade)\n\n  // \"in_progress\" | \"completed\"\n  status      String    @default(\"in_progress\")\n  openedAt    DateTime  @default(now())\n  completedAt DateTime?\n\n  @@unique([enrollmentId, courseId])\n  @@index([courseId])\n  @@map(\"course_progress\")\n}\n\n// Issued when an enrolment is completed. The holder name and formation title\n// are snapshotted so the certificate stays valid and verifiable even if the\n// account or the formation is later renamed. At most one per enrolment.\nmodel Certification {\n  id                String     @id @default(uuid())\n  // Public, unguessable identifier used for verification. Generated by the\n  // application (P2-05), never sequential.\n  certificateNumber String     @unique\n  enrollmentId      String     @unique\n  enrollment        Enrollment @relation(fields: [enrollmentId], references: [id], onDelete: Cascade)\n\n  holderName         String\n  formationTitle     String\n  // Name of the certification as defined by the admin when it was issued\n  // (nullable: falls back to the formation title when the admin left it empty).\n  certificationTitle String?\n  issuedAt           DateTime @default(now())\n\n  // Revocation (P3-16, admin only): the certificate stays on record (never deleted, the\n  // learner's achievement is not erased) but public verification and the learner's own\n  // page show it as revoked. `revokedReason` implies `revokedAt` (CHECK in the migration).\n  revokedAt     DateTime?\n  revokedReason String?   @db.Text\n\n  @@map(\"certifications\")\n}\n\n// ---------------------------------------------------------------------------\n// Blog (P3-01)\n//\n// Same conventions as E-Learning: string status guarded by CHECK constraints\n// (see the blog_model migration), files live in the shared private Media store,\n// the author is a User whose deletion never deletes the article.\n// ---------------------------------------------------------------------------\n\nmodel ArticleCategory {\n  id        String   @id @default(uuid())\n  slug      String   @unique\n  name      String\n  createdAt DateTime @default(now())\n\n  articles Article[]\n\n  @@map(\"article_categories\")\n}\n\nmodel Tag {\n  id        String   @id @default(uuid())\n  slug      String   @unique\n  name      String\n  createdAt DateTime @default(now())\n\n  articles ArticleTag[]\n\n  @@map(\"tags\")\n}\n\n// One blog article. Only the sanitised HTML \"body\" is stored for reading;\n// \"bodyText\" is its plain-text copy, kept in sync by the application, used for\n// search and reading time (parsing HTML on every list request would be wasteful).\nmodel Article {\n  id          String    @id @default(uuid())\n  slug        String    @unique\n  // Language the title / excerpt / body are WRITTEN in (fr | en | ar). Other\n  // languages live in article_translations; a visitor whose language has no\n  // translation simply gets this one.\n  language    String    @default(\"fr\")\n  title       String\n  // Short summary shown on cards and used as the default page description.\n  excerpt     String    @default(\"\") @db.Text\n  body        String?   @db.MediumText\n  bodyText    String    @default(\"\") @db.MediumText\n  // \"draft\" | \"published\". Only published articles are public.\n  status      String    @default(\"draft\")\n  publishedAt DateTime?\n\n  // Visibility by profile (P3-04). \"standard\" = readable by every visitor,\n  // \"premium\" = the text and files need a premium account (the card, title and\n  // excerpt stay public as a teaser). Enforced by the server, never only in the UI.\n  requiredAccessLevel String @default(\"standard\")\n  // Account types this article is recommended to (values of ACCOUNT_TYPES).\n  // Empty = for everybody. It only ORDERS recommendations, it never hides anything.\n  // JSON array (no array column type on MySQL/MariaDB) — membership is checked\n  // in application code (blogAccess.js), not with a DB-side array filter.\n  targetAccountTypes  Json   @default(\"[]\")\n\n  categoryId String?\n  category   ArticleCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n\n  coverImageId String? @unique\n  coverImage   Media?  @relation(\"ArticleCover\", fields: [coverImageId], references: [id], onDelete: SetNull)\n\n  // Deleting the author's account (right to erasure) keeps the article.\n  authorId String?\n  author   User?   @relation(fields: [authorId], references: [id], onDelete: SetNull)\n\n  // SEO: both optional, the page falls back to the title / excerpt.\n  // Level and theme of the \"Apprendre\" search (P2-08). Optional: the blog\n  // existed before, and an article without them is simply not filtered out\n  // by an axis it does not carry.\n  level           String?\n  theme           String? @db.VarChar(60)\n  metaTitle       String?\n  metaDescription String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tags         ArticleTag[]\n  media        Media[]              @relation(\"ArticleMedia\")\n  translations ArticleTranslation[]\n\n  @@index([status, publishedAt])\n  @@index([categoryId])\n  @@map(\"articles\")\n}\n\n// The language-dependent part of an article (title, summary, text, SEO) in ONE\n// other language. Everything else (address, cover, files, category, tags,\n// status, access level) stays on the article and is shared by all languages.\nmodel ArticleTranslation {\n  id              String   @id @default(uuid())\n  articleId       String\n  article         Article  @relation(fields: [articleId], references: [id], onDelete: Cascade)\n  language        String\n  title           String\n  excerpt         String   @default(\"\") @db.Text\n  body            String?  @db.MediumText\n  bodyText        String   @default(\"\") @db.MediumText\n  metaTitle       String?\n  metaDescription String?\n  // true = this row is a raw COPY of the article's own text (from \"duplicate to\n  // start\"), not yet reviewed by a human: it must never be shown to a visitor as\n  // a real translation. An explicit save (saveTranslation) always clears it.\n  pending         Boolean  @default(false)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@unique([articleId, language])\n  @@map(\"article_translations\")\n}\n\nmodel ArticleTag {\n  articleId String\n  tagId     String\n  article   Article @relation(fields: [articleId], references: [id], onDelete: Cascade)\n  tag       Tag     @relation(fields: [tagId], references: [id], onDelete: Cascade)\n\n  @@id([articleId, tagId])\n  @@index([tagId])\n  @@map(\"article_tags\")\n}\n\n// ---------------------------------------------------------------------------\n// Newsletter (P3-05). Double opt-in: an address is only \"confirmed\" once its\n// owner clicked the link sent to it; the confirmation date is the proof of\n// consent. Links carry a signed token (HMAC) computed from the row id, so no\n// token is stored. Deleting a row erases the person completely.\n// ---------------------------------------------------------------------------\nmodel NewsletterSubscriber {\n  id     String @id @default(uuid())\n  // Always stored lower-cased and trimmed (CHECK in the migration).\n  email  String @unique @db.VarChar(254)\n  // \"pending\" | \"confirmed\" | \"unsubscribed\"\n  status String @default(\"pending\")\n  // Language of the subscriber's interface, for the language of the e-mails.\n  locale String @default(\"fr\")\n\n  createdAt      DateTime  @default(now())\n  confirmedAt    DateTime?\n  unsubscribedAt DateTime?\n  // Last confirmation e-mail sent: limits how often one address can be mailed.\n  lastEmailAt    DateTime?\n\n  @@index([status])\n  @@map(\"newsletter_subscribers\")\n}\n\n// A chapter of a formation (P3-11): groups lessons. A chapter that still contains\n// lessons cannot be deleted (RESTRICT): progress lives on the lessons.\nmodel Section {\n  id          String    @id @default(uuid())\n  formationId String\n  formation   Formation @relation(fields: [formationId], references: [id], onDelete: Cascade)\n\n  title       String\n  description String? @db.Text\n  position    Int\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  courses Course[]\n  quizzes Quiz[]\n\n  // Target of the composite foreign key from courses.\n  @@unique([id, formationId])\n  @@index([formationId, position])\n  @@map(\"sections\")\n}\n\n// ---------------------------------------------------------------------------\n// Content of a lesson as an ordered list of typed blocks (P3-12). The server validates\n// `data` for each type (services/blocks.service.js): the browser never sends raw HTML that\n// is stored as is. `courses.body` and the files attached before blocks existed are kept\n// (expand / contract): a lesson WITHOUT blocks is still read the old way.\n// ---------------------------------------------------------------------------\nmodel LessonBlock {\n  id       String @id @default(uuid())\n  courseId String\n  course   Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  // text | image | video | file | code | table | quote | callout | resources (CHECK)\n  type     String\n  position Int\n  data     Json   @default(\"{}\")\n\n  // image / video / file blocks show a file of the same lesson.\n  mediaId String?\n  media   Media?  @relation(fields: [mediaId, courseId], references: [id, courseId], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([courseId, position])\n  @@map(\"lesson_blocks\")\n}\n\n// Snapshot of the blocks of a lesson: history with restoration. Taken automatically (at most\n// one every few minutes while editing) and on demand.\nmodel LessonRevision {\n  id       String @id @default(uuid())\n  courseId String\n  course   Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  blocks Json\n  label  String?\n\n  createdById String?\n  createdBy   User?    @relation(fields: [createdById], references: [id], onDelete: SetNull)\n  createdAt   DateTime @default(now())\n\n  @@index([courseId, createdAt])\n  @@map(\"lesson_revisions\")\n}\n\n// ---------------------------------------------------------------------------\n// Quizzes (P3-13). A quiz is attached to a lesson, to a chapter or to the END of the\n// formation (at most one per target). Correct answers, explanations and accepted answers\n// NEVER leave the server before a learner has submitted an attempt; grading is done by the\n// server. A REQUIRED quiz must be passed to finish the formation (and get the certificate).\n// ---------------------------------------------------------------------------\nmodel Quiz {\n  id          String    @id @default(uuid())\n  formationId String\n  formation   Formation @relation(\"FormationQuizzes\", fields: [formationId], references: [id], onDelete: Cascade)\n\n  // \"course\" (a lesson) | \"section\" (a chapter) | \"formation\" (the end of it). CHECK in the migration.\n  scope            String\n  courseId         String?\n  course           Course?    @relation(fields: [courseId, formationId], references: [id, formationId], onDelete: Cascade)\n  sectionId        String?\n  section          Section?   @relation(fields: [sectionId, formationId], references: [id, formationId], onDelete: Cascade)\n  // Set (to the formation id) only for the final quiz: makes \"one final quiz per formation\" a unique key.\n  finalFormationId String?    @unique\n  finalOf          Formation? @relation(\"FinalQuiz\", fields: [finalFormationId], references: [id], onDelete: Cascade)\n\n  title            String\n  instructions     String  @default(\"\") @db.Text\n  // Percentage of the points needed to pass (0..100).\n  passingScore     Int     @default(70)\n  // null = unlimited attempts.\n  maxAttempts      Int?\n  shuffleQuestions Boolean @default(false)\n  // A required quiz must be passed to finish the formation.\n  isRequired       Boolean @default(false)\n  // Show the right answers and the explanations after an attempt.\n  showCorrection   Boolean @default(true)\n  // Denormalised: true when the quiz has questions and every question is well formed (a right\n  // answer, enough choices...). Kept up to date by the CMS at every change; only a complete quiz\n  // is served to learners, and only a complete REQUIRED quiz blocks the end of a formation. The\n  // consistency check recomputes it.\n  isComplete       Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  questions QuizQuestion[]\n  attempts  QuizAttempt[]\n\n  @@unique([id, formationId])\n  @@unique([courseId])\n  @@unique([sectionId])\n  @@index([formationId])\n  @@map(\"quizzes\")\n}\n\nmodel QuizQuestion {\n  id     String @id @default(uuid())\n  quizId String\n  quiz   Quiz   @relation(fields: [quizId], references: [id], onDelete: Cascade)\n\n  // \"single\" | \"multiple\" | \"true_false\" | \"text\" (CHECK). true_false has exactly two choices\n  // whose texts are \"true\" and \"false\" (the interface translates them).\n  type            String\n  position        Int\n  prompt          String @default(\"\") @db.Text\n  // Shown after the correction.\n  explanation     String @default(\"\") @db.Text\n  points          Int    @default(1)\n  // \"text\" questions: the answers accepted (compared without case, accents or extra spaces).\n  // JSON array (no array column type on MySQL/MariaDB).\n  acceptedAnswers Json   @default(\"[]\")\n\n  choices QuizChoice[]\n\n  @@index([quizId, position])\n  @@map(\"quiz_questions\")\n}\n\nmodel QuizChoice {\n  id         String       @id @default(uuid())\n  questionId String\n  question   QuizQuestion @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  position   Int\n  text       String       @db.Text\n  isCorrect  Boolean      @default(false)\n\n  @@index([questionId, position])\n  @@map(\"quiz_choices\")\n}\n\n// One try of a learner. Created when the learner starts (the questions are served then, without\n// the answers), completed when the learner submits (graded by the server, once).\nmodel QuizAttempt {\n  id           String     @id @default(uuid())\n  quizId       String\n  formationId  String\n  quiz         Quiz       @relation(fields: [quizId, formationId], references: [id, formationId], onDelete: Cascade)\n  enrollmentId String\n  enrollment   Enrollment @relation(fields: [enrollmentId, formationId], references: [id, formationId], onDelete: Cascade)\n\n  startedAt     DateTime  @default(now())\n  submittedAt   DateTime?\n  // Order the questions were served in (fixed per attempt, so resuming shows the same order).\n  // JSON array (no array column type on MySQL/MariaDB).\n  questionOrder Json      @default(\"[]\")\n  score         Int?\n  earnedPoints  Int?\n  totalPoints   Int?\n  passed        Boolean?\n\n  answers QuizAttemptAnswer[]\n\n  @@index([enrollmentId, quizId])\n  @@index([quizId])\n  @@map(\"quiz_attempts\")\n}\n\nmodel QuizAttemptAnswer {\n  id         String      @id @default(uuid())\n  attemptId  String\n  attempt    QuizAttempt @relation(fields: [attemptId], references: [id], onDelete: Cascade)\n  // No foreign key: the history of a graded attempt outlives an edited question.\n  questionId String\n  // JSON array (no array column type on MySQL/MariaDB).\n  choiceIds  Json        @default(\"[]\")\n  text       String      @default(\"\") @db.Text\n  correct    Boolean\n  points     Int\n\n  @@unique([attemptId, questionId])\n  @@map(\"quiz_attempt_answers\")\n}\n\n// ---------------------------------------------------------------------------\n// Bank comparator (P4-06)\n//\n// Built from the client's workbooks (conditions of 13 Algerian banks, 11\n// rubrics). Texts are kept exactly as provided; the rubrics and their columns\n// are defined in src/constants/comparator.js.\n// ---------------------------------------------------------------------------\n\nmodel ComparatorBank {\n  id         String                @id @default(uuid())\n  // As the client writes it (e.g. \"BNP Paribas\", \"TBA\"): no full name is invented.\n  name       String                @unique\n  createdAt  DateTime              @default(now())\n  updatedAt  DateTime              @updatedAt\n  conditions ComparatorCondition[]\n\n  @@map(\"comparator_banks\")\n}\n\nmodel ComparatorCondition {\n  id        String         @id @default(uuid())\n  bankId    String\n  bank      ComparatorBank @relation(fields: [bankId], references: [id], onDelete: Cascade)\n  // One of COMPARATOR_THEMES (CHECK in the migration).\n  theme     String\n  // particulier | professionnel | entreprise | non_precise — set only when the\n  // client's file states it (CHECK in the migration).\n  segment   String         @default(\"non_precise\")\n  // Only for the rubrics that have a \"Catégorie\" column (e.g. Retrait / Versement).\n  category  String?\n  // Account type, operation, card, product... (the rubric's first column).\n  label     String         @db.Text\n  // { field: text } — the rubric's own columns, as written by the client.\n  values    Json           @default(\"{}\")\n  // Order of the client's file within a rubric; new rows go last.\n  position  Int            @default(0)\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  @@index([theme, position])\n  @@index([bankId])\n  @@map(\"comparator_conditions\")\n}\n\n// One row (id = 1): when the comparator's data last changed, for the public\n// \"données mises à jour le\". Every administration write moves it, deletions\n// included (a deleted row leaves no updatedAt behind to read).\nmodel ComparatorMeta {\n  id            Int      @id @default(1)\n  dataUpdatedAt DateTime @default(now())\n\n  @@map(\"comparator_meta\")\n}\n\n// ---------------------------------------------------------------------------\n// Espace entreprise (P7-02) — le socle de l'ERP annoncé par l'annexe 1 du\n// contrat : entreprises, PME, PMI, micro-entreprises, auto-entrepreneurs,\n// micro-importateurs et professions libérales.\n//\n// CE QUI EST MODÉLISÉ ICI ne dépend d'aucun référentiel comptable : des tiers,\n// des documents de vente et d'achat tels que l'entreprise les émet ou les\n// reçoit, et les règlements qui les soldent. De quoi répondre à « qui me doit\n// quoi, qu'est-ce que je dois, et combien est réellement entré ce mois-ci ».\n//\n// CE QUI N'EST PAS MODÉLISÉ, et pourquoi : bilan, compte de résultat, TVA à\n// déclarer, amortissements, stock. Tout cela suppose le Système Comptable\n// Financier algérien et des règles fiscales datées que le client n'a pas\n// fournies. Les inventer produirait des états faux présentés comme\n// comptables — la faute la plus coûteuse que ce projet puisse commettre.\n// Voir `P7-01` et `BUSINESS_BLOCKED_STATEMENTS`.\n//\n// Le socle de métadonnées de `P6-02` s'applique à chaque table qui porte un\n// montant : scope, source, sourceRef, status, confidence, consentUses,\n// effectiveAt, collectedAt, version, archivedAt, deletedAt.\n\nmodel FinBusiness {\n  id                   String                @id @default(uuid())\n  userId               String                @unique\n  user                 User                  @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name                 String                @db.VarChar(160)\n  // Forme juridique DÉCLARÉE par le compte, pas déduite : les obligations\n  // attachées à chaque forme relèvent du droit algérien, que nous ne\n  // modélisons pas (P7-01).\n  legalForm            String?               @db.VarChar(40)\n  // Identifiants fiscaux et commerciaux : saisis tels quels, jamais validés\n  // contre un format inventé. Un NIF refusé à tort empêche d'enregistrer une\n  // entreprise réelle.\n  taxId                String?               @db.VarChar(40)\n  tradeRegister        String?               @db.VarChar(40)\n  statisticalId        String?               @db.VarChar(40)\n  activity             String?               @db.VarChar(160)\n  currency             String                @db.VarChar(3)\n  // Début de l'exercice : un mois (1-12). Le client n'a fourni aucune règle\n  // d'exercice, donc il est déclaré et non supposé janvier.\n  fiscalYearStartMonth Int                   @default(1)\n  scope                String                @default(\"business\") @db.VarChar(20)\n  source               String                @db.VarChar(20)\n  sourceRef            String?               @db.VarChar(200)\n  status               String                @db.VarChar(20)\n  consentUses          Json                  @default(\"[]\")\n  effectiveAt          DateTime              @default(now())\n  collectedAt          DateTime              @default(now())\n  version              Int                   @default(1)\n  archivedAt           DateTime?\n  deletedAt            DateTime?\n  createdAt            DateTime              @default(now())\n  updatedAt            DateTime              @updatedAt\n  contacts             FinBusinessContact[]\n  documents            FinBusinessDocument[]\n  payments             FinBusinessPayment[]\n\n  @@map(\"fin_businesses\")\n}\n\nmodel FinBusinessContact {\n  id          String                @id @default(uuid())\n  businessId  String\n  business    FinBusiness           @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  // \"client\" | \"supplier\" (BUSINESS_CONTACT_KINDS). Un même tiers peut être\n  // les deux : il est alors enregistré deux fois, parce qu'un client et un\n  // fournisseur n'ont ni le même solde ni le même délai.\n  kind        String                @db.VarChar(10)\n  name        String                @db.VarChar(160)\n  taxId       String?               @db.VarChar(40)\n  email       String?               @db.VarChar(254)\n  phone       String?               @db.VarChar(40)\n  address     String?               @db.VarChar(300)\n  country     String?               @db.VarChar(2)\n  note        String?               @db.VarChar(300)\n  scope       String                @default(\"business\") @db.VarChar(20)\n  source      String                @db.VarChar(20)\n  sourceRef   String?               @db.VarChar(200)\n  status      String                @db.VarChar(20)\n  consentUses Json                  @default(\"[]\")\n  effectiveAt DateTime              @default(now())\n  collectedAt DateTime              @default(now())\n  version     Int                   @default(1)\n  archivedAt  DateTime?\n  deletedAt   DateTime?\n  createdAt   DateTime              @default(now())\n  updatedAt   DateTime              @updatedAt\n  documents   FinBusinessDocument[]\n\n  @@index([businessId, kind])\n  @@map(\"fin_business_contacts\")\n}\n\nmodel FinBusinessDocument {\n  id          String               @id @default(uuid())\n  businessId  String\n  business    FinBusiness          @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  contactId   String?\n  contact     FinBusinessContact?  @relation(fields: [contactId], references: [id], onDelete: SetNull)\n  // \"sale\" | \"purchase\" (BUSINESS_DOCUMENT_KINDS) : ce que l'entreprise émet\n  // et ce qu'elle reçoit. Le sens du montant en dépend entièrement.\n  kind        String               @db.VarChar(10)\n  number      String               @db.VarChar(40)\n  label       String               @db.VarChar(200)\n  issuedAt    DateTime\n  dueAt       DateTime?\n  // Montants en centimes, comme partout dans le moteur. Hors taxe et taxe sont\n  // DÉCLARÉS tous les deux : le taux de TVA appliqué appartient au document\n  // réel, et aucun taux n'est supposé ici (voir P7-01).\n  amountExcl  Int\n  taxAmount   Int                  @default(0)\n  currency    String               @db.VarChar(3)\n  note        String?              @db.VarChar(300)\n  scope       String               @default(\"business\") @db.VarChar(20)\n  source      String               @db.VarChar(20)\n  sourceRef   String?              @db.VarChar(200)\n  status      String               @db.VarChar(20)\n  confidence  String?              @db.VarChar(20)\n  consentUses Json                 @default(\"[]\")\n  effectiveAt DateTime             @default(now())\n  collectedAt DateTime             @default(now())\n  version     Int                  @default(1)\n  archivedAt  DateTime?\n  deletedAt   DateTime?\n  createdAt   DateTime             @default(now())\n  updatedAt   DateTime             @updatedAt\n  payments    FinBusinessPayment[]\n\n  // Un numéro de document est unique dans l'entreprise qui l'émet : deux\n  // factures portant le même numéro sont une erreur de saisie, pas deux\n  // factures.\n  @@unique([businessId, kind, number])\n  @@index([businessId, issuedAt])\n  @@map(\"fin_business_documents\")\n}\n\nmodel FinBusinessPayment {\n  id          String              @id @default(uuid())\n  businessId  String\n  business    FinBusiness         @relation(fields: [businessId], references: [id], onDelete: Cascade)\n  documentId  String\n  document    FinBusinessDocument @relation(fields: [documentId], references: [id], onDelete: Cascade)\n  value       Int\n  currency    String              @db.VarChar(3)\n  receivedAt  DateTime\n  method      String?             @db.VarChar(20)\n  note        String?             @db.VarChar(300)\n  scope       String              @default(\"business\") @db.VarChar(20)\n  source      String              @db.VarChar(20)\n  sourceRef   String?             @db.VarChar(200)\n  status      String              @db.VarChar(20)\n  consentUses Json                @default(\"[]\")\n  effectiveAt DateTime            @default(now())\n  collectedAt DateTime            @default(now())\n  version     Int                 @default(1)\n  archivedAt  DateTime?\n  deletedAt   DateTime?\n  createdAt   DateTime            @default(now())\n  updatedAt   DateTime            @updatedAt\n\n  @@index([businessId, receivedAt])\n  @@index([documentId])\n  @@map(\"fin_business_payments\")\n}\n\n// A payslip the person chose to keep (P8-15, the client's answer D5:\n// « historique »). Kept only with their explicit consent — P4-14 kept none,\n// a payslip being sensitive. The lines as typed, and what the decoder made of\n// them; the net feeds the monthly income only when the person confirms.\nmodel FinPayslip {\n  id          String    @id @default(uuid())\n  userId      String\n  user        User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  period      String?   @db.VarChar(20)\n  // [{ kind, label, value }] as the decoder accepts them.\n  lines       Json\n  // In centimes: the gross, the net the lines give, the net printed on it.\n  gross       Int\n  value       Int\n  declaredNet Int?\n  currency    String    @default(\"DZD\") @db.VarChar(3)\n  scope       String    @default(\"personal\") @db.VarChar(20)\n  source      String    @db.VarChar(20)\n  status      String    @db.VarChar(20)\n  confidence  String?   @db.VarChar(10)\n  consentUses Json      @default(\"[]\")\n  effectiveAt DateTime  @default(now())\n  collectedAt DateTime  @default(now())\n  version     Int       @default(1)\n  deletedAt   DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@index([userId, deletedAt])\n  @@map(\"fin_payslips\")\n}\n\n// A signed-in device (P8-20, « appareils et sessions connectés »). The cookie\n// carries this row's id (`jti`): revoking the row ends that session on its\n// very next request. Only a coarse device label is kept — no address, no\n// precise fingerprint — because the person needs to recognise a device, not\n// be tracked.\nmodel UserSession {\n  id         String    @id @default(uuid())\n  userId     String\n  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  device     String    @db.VarChar(120)\n  createdAt  DateTime  @default(now())\n  lastSeenAt DateTime  @default(now())\n  revokedAt  DateTime?\n\n  @@index([userId, revokedAt])\n  @@map(\"user_sessions\")\n}\n\n// A common budget (P9-05, COL-F06 / F07): one envelope per category and month\n// of a space. It belongs to the space and touches NO personal budget (QC-06):\n// the only thing it reads is the space's own shared expenses.\nmodel FinSpaceBudget {\n  id        String    @id @default(uuid())\n  spaceId   String\n  space     FinSpace  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  // COLC-nn, one of the 19 collective categories.\n  category  String    @db.VarChar(8)\n  // `YYYY-MM`.\n  period    String    @db.VarChar(7)\n  value     Int\n  setById   String\n  version   Int       @default(1)\n  deletedAt DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@unique([spaceId, category, period])\n  @@index([spaceId, period])\n  @@map(\"fin_space_budgets\")\n}\n\n// A task of a space (P9-06, tab 08 of the collective workbook): chores, bills to\n// pay, errands. A module apart from the finances — it is linked to an expense\n// or a bill for information only, and NEVER creates a financial movement (QC-07).\nmodel FinSpaceTask {\n  id              String    @id @default(uuid())\n  spaceId         String\n  space           FinSpace  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  title           String    @db.VarChar(120)\n  description     String?   @db.VarChar(500)\n  // One of TASK_CATEGORIES (constants/finSpaceTask.js).\n  category        String    @db.VarChar(20)\n  // A MEMBERSHIP, like the payer of an expense: it survives the member leaving.\n  assigneeId      String\n  // Other members taking part: a JSON list of membership ids.\n  participants    Json      @default(\"[]\")\n  dueDate         DateTime?\n  priority        String    @default(\"normal\") @db.VarChar(10)\n  // none, daily, weekly, monthly (ALG-C04).\n  recurrence      String    @default(\"none\") @db.VarChar(10)\n  // [{ label, done }]\n  checklist       Json      @default(\"[]\")\n  // The client's rule A2: the weight of a task, 1, 2 or 3 (default 1).\n  weight          Int       @default(1)\n  status          String    @default(\"todo\") @db.VarChar(10)\n  completedAt     DateTime?\n  // Days before the due date at which the person is reminded.\n  reminderDays    Int?\n  // Informative links only.\n  linkedExpenseId String?\n  createdById     String\n  version         Int       @default(1)\n  deletedAt       DateTime?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  @@index([spaceId, status])\n  @@index([spaceId, dueDate])\n  @@map(\"fin_space_tasks\")\n}\n\n// What comes INTO a space's common pot (P9-09, the client's rule A1): the\n// opening balance, the contributions members make, other entries. Only a\n// `confirmed` one counts; a planned contribution is a promise, not money.\n//   common resources = opening balance + confirmed contributions + other\n//                      confirmed entries\n//   group balance    = common resources - realised expenses\nmodel FinSpaceInflow {\n  id           String    @id @default(uuid())\n  spaceId      String\n  space        FinSpace  @relation(fields: [spaceId], references: [id], onDelete: Cascade)\n  // opening, contribution, other\n  kind         String    @db.VarChar(12)\n  // The member who contributed, for a contribution.\n  memberId     String?\n  value        Int\n  occurredAt   DateTime\n  status       String    @default(\"confirmed\") @db.VarChar(10)\n  note         String?   @db.VarChar(300)\n  recordedById String\n  version      Int       @default(1)\n  deletedAt    DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@index([spaceId, status])\n  @@map(\"fin_space_inflows\")\n}\n\n// What was true at a date, kept as it was (P8-24): a monthly report the person\n// chose to keep, and the month's financial-health index. A snapshot is never\n// recomputed — that is the point: a later correction of an old movement does not\n// rewrite what the person saw then. One per (person, kind, month); keeping the\n// same month again replaces it and says so (`version`).\nmodel FinSnapshot {\n  id         String   @id @default(uuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  // `report` or `health`.\n  kind       String   @db.VarChar(10)\n  // `YYYY-MM`.\n  period     String   @db.VarChar(7)\n  payload    Json\n  version    Int      @default(1)\n  capturedAt DateTime @default(now())\n\n  @@unique([userId, kind, period])\n  @@map(\"fin_snapshots\")\n}\n\n// A pedagogical mission (P8-17): a short series of choices on a FICTIVE sum, whose\n// contents are written by the client and entered by an administrator. See\n// constants/finMissions.js for the scoring rule, which is the same for every one.\nmodel FinMission {\n  id             String              @id @default(uuid())\n  slug           String              @unique @db.VarChar(80)\n  title          String              @db.VarChar(120)\n  summary        String              @db.VarChar(500)\n  // Education profile codes it is offered to; an empty list means everybody.\n  profiles       Json                @default(\"[]\")\n  startingAmount Int\n  currency       String              @db.VarChar(3)\n  // [{ key, prompt, choices: [{ key, label, cash, savings, resilience, explanation }] }]\n  steps          Json\n  // [{ key, label, minResilience }]\n  badges         Json                @default(\"[]\")\n  status         String              @default(\"draft\") @db.VarChar(10)\n  position       Int                 @default(0)\n  version        Int                 @default(1)\n  publishedAt    DateTime?\n  createdAt      DateTime            @default(now())\n  updatedAt      DateTime            @updatedAt\n  attempts       FinMissionAttempt[]\n\n  @@index([status, position])\n  @@map(\"fin_missions\")\n}\n\n// One play of a mission. Kept (the last few per person) so a badge can be shown\n// and a mission replayed; it holds only the choices and the computed result.\nmodel FinMissionAttempt {\n  id        String     @id @default(uuid())\n  userId    String\n  user      User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  missionId String\n  mission   FinMission @relation(fields: [missionId], references: [id], onDelete: Cascade)\n  choices   Json\n  result    Json\n  createdAt DateTime   @default(now())\n\n  @@index([userId, missionId])\n  @@map(\"fin_mission_attempts\")\n}\n\n// A browser that agreed to receive the person's notifications (P8-24, Web Push).\n// One row per browser; the endpoint is the push service's own address for it and\n// is secret enough that it is never sent to anybody else. Removed the moment the\n// push service says the browser is gone (404 / 410) or the person turns it off.\nmodel FinPushSubscription {\n  id         String    @id @default(uuid())\n  userId     String\n  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  endpoint   String    @unique @db.VarChar(700)\n  p256dh     String    @db.VarChar(200)\n  auth       String    @db.VarChar(100)\n  // The browser's own name, from its User-Agent — what the person recognises in\n  // their list; no address, no fingerprint (same rule as the sessions).\n  label      String    @db.VarChar(80)\n  createdAt  DateTime  @default(now())\n  lastSentAt DateTime?\n\n  @@index([userId])\n  @@map(\"fin_push_subscriptions\")\n}\n"
}

